INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('584476ca-e9d2-587f-827b-aaf1a908880d', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 9, 9, 'How does the spacing of the field lines around a long straight current-carrying wire change with distance from the wire?', NULL, 1, 'multiple_choice'::answer_type, 'The circles get further apart, showing a weaker field', NULL, false, NULL, false, NULL, 'The field strength falls with distance, so the concentric circles are drawn further apart. Mark scheme (1 mark). B1: C (The circles get further apart, showing a weaker field).', 1),
('a6a6193a-9bef-5900-97cb-9b1646c89b78', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 10, 10, 'How is the right-hand grip rule used for a solenoid?', NULL, 1, 'multiple_choice'::answer_type, 'Curl the fingers in the direction of the current in the turns; the thumb points to the north-pole end', NULL, false, NULL, false, NULL, 'For a coil or solenoid, the thumb gives the direction of the field inside, which leaves at the north end. Mark scheme (1 mark). B1: A (Curl the fingers in the direction of the current in the turns; the thumb points to the north-pole end).', 1),
('509c9bb5-2d25-5950-bc01-3de9dadc4506', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 11, 11, 'The current in a straight wire is reversed. What happens to its magnetic field?', NULL, 1, 'multiple_choice'::answer_type, 'The field direction reverses but its pattern stays the same', NULL, false, NULL, false, NULL, 'The direction of the field circles follows the direction of the current. Mark scheme (1 mark). B1: D (The field direction reverses but its pattern stays the same).', 1),
('934b2fd0-d050-5fae-a5ac-ea8b187be2c7', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 12, 12, 'Why is a soft iron core placed inside a solenoid to make an electromagnet?', NULL, 1, 'multiple_choice'::answer_type, 'It makes the magnetic field very much stronger', NULL, false, NULL, false, NULL, 'Iron is easily magnetised and greatly concentrates the field, and soft iron loses its magnetism when the current stops. Mark scheme (1 mark). B1: B (It makes the magnetic field very much stronger).', 1),
('6e1c29fc-80c3-5805-9b85-957d994da027', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 13, 13, 'The magnetic flux density a distance r from a long straight wire is B = µ₀I/2πr. Calculate B at 0.020 m from a wire carrying 5.0 A, in µT. Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 1, 'numeric'::answer_type, '50 uT', 'µT', false, NULL, false, NULL, 'B = 2.0 × 10⁻⁷ × 5.0 ÷ 0.020 = 5.0 × 10⁻⁵ T. In µT: 5.0 × 10⁻⁵ × 10⁶ = 50. Mark scheme (2 marks). C1: B = µ₀I/2πr. A1: B = 50 µT.', 2),
('dee83753-afe5-5788-a08d-b336c57457d6', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 14, 14, 'The flux density inside a long solenoid is B = µ₀nI, where n is the number of turns per metre. Calculate B for n = 2000 m⁻¹ and I = 1.5 A, in mT. Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 1, 'numeric'::answer_type, '3.77 mT', 'mT', false, NULL, false, NULL, 'B = 4π × 10⁻⁷ × 2000 × 1.5 = 0.00377 T. In mT: 0.003770 × 1000 = 3.77. Mark scheme (2 marks). C1: B = µ₀nI. A1: B = 3.77 mT.', 2),
('d1ef4a8d-b684-5114-9cef-ab5ce802187d', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 15, 15, 'What is the direction of the magnetic field at the centre of a flat circular coil carrying a current?', NULL, 1, 'multiple_choice'::answer_type, 'Perpendicular to the plane of the coil', NULL, false, NULL, false, NULL, 'The contributions from every part of the coil point the same way through the centre, along its axis. Mark scheme (1 mark). B1: C (Perpendicular to the plane of the coil).', 1),
('f59ea6d2-36bb-5abc-a1ce-50e260e66ce8', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 16, 16, 'What is the main advantage of an electromagnet over a permanent magnet?', NULL, 1, 'multiple_choice'::answer_type, 'Its field can be switched off and its strength changed by changing the current', NULL, false, NULL, false, NULL, 'B depends on the current, which can be controlled. Mark scheme (1 mark). B1: A (Its field can be switched off and its strength changed by changing the current).', 1),
('af653152-2fe5-512e-8ba2-57f2812dd9c5', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 17, 17, 'The flux density 4.0 cm from a long straight wire is 30 µT. What is it 8.0 cm from the wire, in µT? (B ∝ 1/r.)', NULL, 1, 'numeric'::answer_type, '15 uT', 'µT', false, NULL, false, NULL, 'B ∝ 1/r, so doubling r halves B: 30 × 4.0 ÷ 8.0 = 15 µT. Mark scheme (2 marks). C1: B ∝ 1/r. A1: B = 15 µT.', 2),
('d7baec58-a495-5a89-a826-c4372b741a14', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 18, 18, 'Looking at one end of a solenoid, you see the current flowing anticlockwise. Which pole is at that end?', NULL, 1, 'multiple_choice'::answer_type, 'North', NULL, false, NULL, false, NULL, 'Anticlockwise current seen from an end makes that end a north pole (grip rule). Mark scheme (1 mark). B1: D (North).', 1),
('83ce43cf-1954-52e2-8a43-a139c1f8f885', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 19, 19, 'A solenoid has 500 turns wound evenly along a length of 0.25 m. Calculate the number of turns per metre, n.', NULL, 1, 'numeric'::answer_type, '2000', 'm⁻¹', false, NULL, false, NULL, 'n = N/L = 500 ÷ 0.25 = 2000 m⁻¹. Mark scheme (2 marks). C1: n = N/L. A1: n = 2000 m⁻¹.', 2),
('feccef9c-d327-578d-a365-3c0dd7e6c422', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 20, 20, 'Where is the magnetic field of a long solenoid strongest?', NULL, 1, 'multiple_choice'::answer_type, 'Inside the solenoid, away from its ends', NULL, false, NULL, false, NULL, 'Inside, the fields of all the turns add; outside they largely cancel. Mark scheme (1 mark). B1: B (Inside the solenoid, away from its ends).', 1),
('0e9d9887-69be-589a-9218-d6394e330d97', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 21, 21, 'A solenoid has 4000 turns per metre. Calculate the current needed to give a flux density of 2.0 mT inside it, using B = µ₀nI. Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 1, 'numeric'::answer_type, '0.3979', 'A', false, NULL, false, NULL, 'I = B/(µ₀n) = 2.0 × 10⁻³ ÷ (4π × 10⁻⁷ × 4000) = 0.398 A. Mark scheme (2 marks). C1: I = B/(µ₀n). A1: I = 0.398 A.', 2),
('4390532a-c063-5597-9111-6fbcecb9e45d', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 22, 22, 'In which direction do magnetic field lines point outside a bar magnet?', NULL, 1, 'multiple_choice'::answer_type, 'From the north pole to the south pole', NULL, false, NULL, false, NULL, 'Field lines show the direction a free north pole would move. Mark scheme (1 mark). B1: C (From the north pole to the south pole).', 1),
('21873400-1ccc-5715-bcb1-535d0509b501', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 23, 23, 'The flux density inside a solenoid is 0.60 mT. The current is tripled. What is the new flux density, in mT?', NULL, 1, 'numeric'::answer_type, '1.8 mT', 'mT', false, NULL, false, NULL, 'B ∝ I: 3 × 0.60 = 1.8 mT. Mark scheme (1 mark). A1: B = 1.8 mT.', 1),
('d5e1034f-509e-580d-8958-3638b5568130', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 24, 24, 'A compass needle lies where the Earth''s horizontal field is 2.0 × 10⁻⁵ T due north. A nearby wire adds a horizontal field of 1.5 × 10⁻⁵ T due east. Calculate the angle the needle turns through from north.', NULL, 2, 'numeric'::answer_type, '36.87', '°', false, NULL, false, NULL, 'The needle lines up with the resultant field: tan θ = 1.5 × 10⁻⁵ ÷ 2.0 × 10⁻⁵ = 0.75, so θ = tan⁻¹ 0.75 = 36.9°. Mark scheme (3 marks). M1: needle follows resultant. C1: tan θ = B_wire/B_Earth. A1: θ = 36.9°.', 3),
('e6765316-1dcc-5998-82eb-9397ca3f8b20', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 25, 25, 'How far from a long straight wire carrying 10 A is the flux density 1.0 × 10⁻⁵ T? (B = µ₀I/2πr.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '0.2', 'm', false, NULL, false, NULL, 'r = (µ₀/2π) × I ÷ B = 2.0 × 10⁻⁷ × 10 ÷ 1.0 × 10⁻⁵ = 0.20 m. Mark scheme (3 marks). C1: rearranged for r. C1: substitution. A1: r = 0.20 m.', 3),
('75d867ea-79f0-5ba3-8c87-1f7f9a8b6eeb', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 26, 26, 'Two long parallel wires are 10 cm apart and each carries 4.0 A, in opposite directions. Calculate the flux density midway between them, in µT. (B = µ₀I/2πr for each wire.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '32 uT', 'µT', false, NULL, false, NULL, 'Each wire gives B = 2.0 × 10⁻⁷ × 4.0 ÷ 0.050 = 1.6 × 10⁻⁵ T. With opposite currents the fields point the same way between the wires: B = 2 × 1.6 × 10⁻⁵ = 3.2 × 10⁻⁵ T. In µT: 3.2 × 10⁻⁵ × 10⁶ = 32. Mark scheme (4 marks). C1: field of one wire. M1: fields add for opposite currents. C1: total. A1: B = 32 µT.', 4),
('3c666571-e3d4-53a5-ac2b-a287ef926c33', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 27, 27, 'Two long parallel wires carry equal currents in the same direction. What is the magnetic field midway between them?', NULL, 2, 'multiple_choice'::answer_type, 'Zero, because the two fields are equal and opposite there', NULL, false, NULL, false, NULL, 'Between the wires, same-direction currents produce opposite field directions. Mark scheme (3 marks). C1: equal magnitudes at midpoint. C1: opposite directions. A1: A (Zero, because the two fields are equal and opposite there).', 3),
('81d6b745-680c-523d-8060-64e20d9a0037', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 28, 28, 'A solenoid 0.40 m long has 800 turns and carries 2.5 A. Calculate the flux density inside it, in mT, using B = µ₀nI. Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '6.283 mT', 'mT', false, NULL, false, NULL, 'n = 800 ÷ 0.40 = 2000 m⁻¹. B = 4π × 10⁻⁷ × 2000 × 2.5 = 0.00628 T. In mT: 0.006283 × 1000 = 6.28. Mark scheme (3 marks). C1: n = N/L. C1: B = µ₀nI. A1: B = 6.28 mT.', 3),
('9db9d254-837f-5dd7-9439-3f17b3cc5fa3', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 29, 29, 'What current in a long straight wire produces a flux density equal to the Earth''s field, 5.0 × 10⁻⁵ T, at a distance of 5.0 cm? (B = µ₀I/2πr.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '12.5', 'A', false, NULL, false, NULL, 'I = B × r ÷ (µ₀/2π) = 5.0 × 10⁻⁵ × 0.050 ÷ 2.0 × 10⁻⁷ = 12.5 A. Mark scheme (3 marks). C1: rearranged for I. C1: substitution. A1: I = 12.5 A.', 3),
('211152d0-d74b-56db-881a-608f701b44f8', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 30, 30, 'A solenoid is stretched to twice its length without changing the number of turns or the current. What happens to the flux density inside?', NULL, 2, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'B = µ₀nI and n = N/L halves. Mark scheme (3 marks). C1: n = N/L halves. C1: B ∝ n. A1: D (It halves).', 3),
('9f4bb2e5-8b26-5a88-b39a-f9f78134727f', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 31, 31, 'The flux density 3.0 cm from a long straight wire is 120 µT. Calculate the flux density 9.0 cm from the wire, in µT.', NULL, 2, 'numeric'::answer_type, '40 uT', 'µT', false, NULL, false, NULL, 'B ∝ 1/r: B = 120 × 3.0 ÷ 9.0 = 40 µT. Mark scheme (3 marks). C1: B ∝ 1/r. C1: ratio. A1: B = 40 µT.', 3),
('5336d2ca-112a-5639-afd2-7b443c88acea', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 32, 32, 'The field pattern of a flat circular coil carrying a current most closely resembles that of which object?', NULL, 2, 'multiple_choice'::answer_type, 'A short bar magnet', NULL, false, NULL, false, NULL, 'One face acts as a north pole and the other as a south pole. Mark scheme (3 marks). C1: poles on the two faces. C1: like a short magnet. A1: B (A short bar magnet).', 3),
('b4610226-f881-51cf-aa57-0b588274d770', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 33, 33, 'A solenoid 0.30 m long must produce 10 mT when carrying 3.0 A. Using B = µ₀NI/L, calculate the number of turns needed. Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '795.8', 'turns', false, NULL, false, NULL, 'N = BL/(µ₀I) = 10 × 10⁻³ × 0.30 ÷ (4π × 10⁻⁷ × 3.0) = 796 turns. Mark scheme (3 marks). C1: rearranged for N. C1: substitution. A1: N = 796 turns.', 3),
('c46075c0-293d-5504-9e32-05578dd096bd', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 34, 34, 'A long vertical wire carries a current upwards. The Earth''s horizontal field points north. On which side of the wire is there a point where the resultant horizontal field is zero?', NULL, 2, 'multiple_choice'::answer_type, 'West of the wire', NULL, false, NULL, false, NULL, 'Viewed from above, the wire''s field circles anticlockwise. To the west of the wire it points south, opposing the Earth''s northward field. Mark scheme (4 marks). C1: grip rule direction. C1: wire field opposite to Earth field. C1: west side. A1: C (West of the wire).', 4),
('734e9952-d322-529f-9074-24a2d4c9155e', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 35, 35, 'The flux density at the centre of a flat circular coil is B = µ₀NI/2r. Calculate B for a coil of 50 turns and radius 0.10 m carrying 2.0 A, in mT. Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '0.6283 mT', 'mT', false, NULL, false, NULL, 'B = 4π × 10⁻⁷ × 50 × 2.0 ÷ (2 × 0.10) = 6.28 × 10⁻⁴ T. In mT: 6.283 × 10⁻⁴ × 1000 = 0.628. Mark scheme (3 marks). C1: B = µ₀NI/2r. C1: substitution. A1: B = 0.628 mT.', 3),
('62ed6252-2dd1-5dfe-a5c2-aa36b9e80008', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 36, 36, 'A laboratory solenoid gives a flux density of 3.0 mT. The Earth''s field is about 5.0 × 10⁻⁵ T. Calculate (solenoid field) ÷ (Earth''s field).', NULL, 2, 'numeric'::answer_type, '60', NULL, false, NULL, false, NULL, 'Ratio = 3.0 × 10⁻³ ÷ 5.0 × 10⁻⁵ = 60. Mark scheme (3 marks). C1: both in tesla. C1: ratio. A1: ratio = 60.', 3),
('114227b6-5b5d-57d2-86b4-7b2e1076e02b', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 37, 37, 'A horizontal wire runs west to east and carries a current towards the east. What is the direction of its magnetic field at a point directly above the wire?', NULL, 2, 'multiple_choice'::answer_type, 'Due south', NULL, false, NULL, false, NULL, 'With the thumb pointing east, the fingers of the right hand curl over the top of the wire towards the south (seen from the west end, the field circles clockwise). Mark scheme (3 marks). C1: right-hand grip rule. C1: direction above the wire. A1: A (Due south).', 3),
('a7270e00-aad9-5f95-a3b7-49aa46bc267d', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 38, 38, 'At a point near a wire, the wire produces a horizontal field of 3.0 × 10⁻⁵ T due west and the Earth''s horizontal field is 4.0 × 10⁻⁵ T due north. Calculate the magnitude of the resultant horizontal field, in µT.', NULL, 2, 'numeric'::answer_type, '50 uT', 'µT', false, NULL, false, NULL, 'B = √((3.0 × 10⁻⁵)² + (4.0 × 10⁻⁵)²) = 5.0 × 10⁻⁵ T. In µT: 5.0 × 10⁻⁵ × 10⁶ = 50. Mark scheme (4 marks). M1: fields add as vectors. C1: Pythagoras. C1: conversion. A1: B = 50 µT.', 4),
('b708e987-b813-5f68-af30-2c8a34b01068', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 39, 39, 'Which change would NOT increase the strength of an electromagnet made from a coil and core?', NULL, 2, 'multiple_choice'::answer_type, 'Replacing the iron core with a copper core', NULL, false, NULL, false, NULL, 'Copper is not ferromagnetic, so it does not concentrate the field. Mark scheme (3 marks). C1: B ∝ nI. C1: copper not magnetic. A1: D (Replacing the iron core with a copper core).', 3),
('3456fd52-d6ad-560b-98c9-cfecc620010a', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 40, 40, 'The flux density 6.0 cm from a long straight wire is 40 µT. Calculate the current in the wire. (B = µ₀I/2πr.) Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '12', 'A', false, NULL, false, NULL, 'I = B × r ÷ (µ₀/2π) = 40 × 10⁻⁶ × 0.060 ÷ 2.0 × 10⁻⁷ = 12 A. Mark scheme (3 marks). C1: rearranged for I. C1: substitution. A1: I = 12 A.', 3),
('a61b620e-c3c1-5711-9a24-669b9ab4cf0a', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 41, 41, 'Two long parallel wires are 0.10 m apart. Wire 1 carries 6.0 A and wire 2 carries 2.0 A in the same direction. (a) Explain why the resultant field is zero at one point between the wires. (b) Write an equation for the distance x of this point from wire 1, using B = µ₀I/2πr. (c) Calculate x, in cm. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '7.5 cm', 'cm', false, NULL, false, NULL, '(a) Between same-direction currents the two fields are opposite; they are equal where the larger current is further away. (b) 6.0/x = 2.0/(0.10 − x). (c) 6.0 × (0.10 − x) = 2.0x, so x = 0.60 ÷ 8.0 = 0.075 m. In cm: 0.075 × 100 = 7.5. Mark scheme (6 marks). B1: fields opposite between wires. M1: equal magnitudes. C1: equation. C1: x = 0.075 m. C1: conversion. A1: x = 7.5 cm.', 6),
('5158bd63-09f7-5808-8a07-ed747d004d6a', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 42, 42, 'A compass is placed 4.0 cm from a long vertical wire, on the line east of it. The wire''s field there is horizontal and at right angles to the Earth''s horizontal field B_E. Readings: I/A = 1.0, 2.0, 3.0, 4.0 and deflection θ/° = 15.5, 29.1, 39.8, 48.0. (a) Show that tan θ = µ₀I/(2πrB_E). (b) Calculate tan θ for the largest reading and use it to find B_E, in µT. Give only the answer to (b). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '18.01 uT', 'µT', false, NULL, false, NULL, '(a) The needle follows the resultant of B_E and the wire''s field B_w at right angles, so tan θ = B_w/B_E = µ₀I/(2πrB_E). (b) tan 48.0° = 1.111. B_w = 2.0 × 10⁻⁷ × 4.0 ÷ 0.040 = 2.0 × 10⁻⁵ T. B_E = 2.0 × 10⁻⁵ ÷ 1.111 = 1.80 × 10⁻⁵ T. In µT: 1.801 × 10⁻⁵ × 10⁶ = 18.0. Mark scheme (6 marks). M1: resultant of perpendicular fields. B1: tan θ expression. C1: wire field. C1: B_E = B_w/tan θ. C1: conversion. A1: B_E = 18.0 µT.', 6),
('22872ca0-1268-577f-89f3-3731aea5a717', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 43, 43, 'A solenoid 0.50 m long must produce a flux density of 25 mT. The wire can safely carry 4.0 A. (a) Using B = µ₀NI/L, calculate the number of turns needed. (b) Each turn uses 0.15 m of wire and the wire has a resistance of 0.020 Ω per metre. Calculate the resistance of the solenoid. (c) Calculate the p.d. needed across it. Give only the answer to (a). Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '2487', 'turns', false, NULL, false, NULL, '(a) N = BL/(µ₀I) = 25 × 10⁻³ × 0.50 ÷ (4π × 10⁻⁷ × 4.0) = 2490 turns. (b) Length = 2487 × 0.15 = 373 m; R = 373.0 × 0.020 = 7.46 Ω. (c) V = IR = 4.0 × 7.460 = 29.8 V. Mark scheme (6 marks). C1: N = BL/(µ₀I). C1: substitution. C1: wire length. C1: resistance. C1: V = IR. A1: N = 2490 turns.', 6),
('2c749df2-897a-5354-9a9e-b696f97f581a', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 44, 44, 'Two long parallel wires A and B, 5.0 cm apart, each carry 6.0 A out of the page. Point P is 3.0 cm from A and 4.0 cm from B, so AP and BP are at right angles. (a) Calculate the flux density at P due to each wire, using B = µ₀I/2πr. (b) Explain why these two fields are at right angles to each other at P. (c) Calculate the resultant flux density at P, in µT. Give only the answer to (c). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '50 uT', 'µT', false, NULL, false, NULL, '(a) B_A = 2.0 × 10⁻⁷ × 6.0 ÷ 0.030 = 4.0 × 10⁻⁵ T; B_B = 2.0 × 10⁻⁷ × 6.0 ÷ 0.040 = 3.0 × 10⁻⁵ T. (b) Each field is perpendicular to the line from its wire to P, and those lines are perpendicular. (c) B = √((4.0 × 10⁻⁵)² + (3.0 × 10⁻⁵)²) = 5.0 × 10⁻⁵ T. In µT: 5.0 × 10⁻⁵ × 10⁶ = 50. Mark scheme (6 marks). C1: B_A. C1: B_B. B1: fields perpendicular. M1: vector addition. C1: conversion. A1: B = 50 µT.', 6),
('492f0415-cff3-5476-90c6-e8263f4cfe6c', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 45, 45, 'A long vertical wire carries 8.0 A. The Earth''s horizontal field is 2.0 × 10⁻⁵ T. (a) Explain why there is a neutral point near the wire. (b) Calculate the distance of the neutral point from the wire, in cm. Give only the answer to (b). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '8 cm', 'cm', false, NULL, false, NULL, '(a) On one side of the wire its circular field is opposite to the Earth''s field; where the magnitudes are equal the resultant is zero. (b) µ₀I/2πr = B_E, so r = 2.0 × 10⁻⁷ × 8.0 ÷ 2.0 × 10⁻⁵ = 0.080 m. In cm: 0.080 × 100 = 8.0. Mark scheme (5 marks). B1: opposite fields on one side. M1: µ₀I/2πr = B_E. C1: r. C1: conversion. A1: r = 8.0 cm.', 5),
('e9a315cb-24f8-558d-afdd-d5f42829bdd1', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 46, 46, 'A solenoid of length 0.60 m and radius 1.5 cm has 1200 turns and carries 0.50 A. A 50-turn search coil is wound tightly round its middle. (a) Calculate the flux density inside the solenoid, using B = µ₀NI/L. (b) Calculate the flux through the solenoid''s cross-section. (c) Calculate the flux linkage of the search coil. Give only the answer to (c). Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '4.441e-5', 'Wb', false, NULL, false, NULL, '(a) B = 4π × 10⁻⁷ × (1200 ÷ 0.60) × 0.50 = 0.00126 T. (b) A = π × 0.015² = 7.07 × 10⁻⁴ m²; Φ = 0.001257 × 7.069 × 10⁻⁴ = 8.88 × 10⁻⁷ Wb. (c) NΦ = 50 × 8.883 × 10⁻⁷ = 4.44 × 10⁻⁵ Wb. Mark scheme (6 marks). C1: n = N/L. C1: B = µ₀nI. C1: A = πr². C1: Φ = BA. C1: NΦ. A1: NΦ = 4.44 × 10⁻⁵ Wb.', 6),
('ff785d7b-88cf-5995-8855-33adb3b279e7', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 47, 47, 'A Hall probe measures the field at distances r from a long straight wire: r/cm = 2.0, 4.0, 6.0, 8.0 and B/µT = 100, 50, 33, 25. (a) Show that B is inversely proportional to r. (b) Calculate the value of Br. (c) Use B = µ₀I/2πr to find the current in the wire. Give only the answer to (c). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '10', 'A', false, NULL, false, NULL, '(a) Br = 100 × 0.020 = 2.0 µT m for every reading (33 × 0.060 = 1.98), so B ∝ 1/r. (b) Br = 100 × 10⁻⁶ × 0.020 = 2.0 × 10⁻⁶ T m. (c) I = Br ÷ (µ₀/2π) = 2.0 × 10⁻⁶ ÷ 2.0 × 10⁻⁷ = 10 A. Mark scheme (6 marks). C1: Br calculated. B1: constant, so B ∝ 1/r. M1: Br = µ₀I/2π. C1: substitution. C1: value. A1: I = 10 A.', 6),
('37027bdc-a7df-5a9c-8016-065e03b67b00', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 48, 48, 'A flat coil of 100 turns and radius 5.0 cm carries 0.40 A. (a) Calculate the flux density at its centre using B = µ₀NI/2r. (b) The same wire is rewound as a solenoid of 100 turns and length 0.20 m. Calculate the flux density inside, using B = µ₀NI/L. (c) Calculate (flat-coil field) ÷ (solenoid field). Give only the answer to (c). Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, '(a) B = 4π × 10⁻⁷ × 100 × 0.40 ÷ 0.10 = 5.03 × 10⁻⁴ T. (b) B = 4π × 10⁻⁷ × 100 × 0.40 ÷ 0.20 = 2.51 × 10⁻⁴ T. (c) Ratio = 5.027 × 10⁻⁴ ÷ 2.513 × 10⁻⁴ = 2.0. Mark scheme (5 marks). C1: flat coil field. C1: solenoid field. C1: ratio. B1: comparison of 2r and L. A1: ratio = 2.0.', 5),
('27b2ec95-af4b-5139-9c54-0b13898f3169', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 49, 49, 'An overhead power cable carries a steady current of 300 A at a height of 10 m above the ground. (a) Calculate the flux density it produces at ground level directly below, in µT, using B = µ₀I/2πr. (b) Compare this with the Earth''s field of about 50 µT. (c) Explain why the field from a mains cable alternates. Give only the answer to (a). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '6 uT', 'µT', false, NULL, false, NULL, '(a) B = 2.0 × 10⁻⁷ × 300 ÷ 10 = 6.0 × 10⁻⁶ T. In µT: 6.0 × 10⁻⁶ × 10⁶ = 6.0. (b) It is about an eighth of the Earth''s field. (c) Mains current alternates, so the field reverses direction 100 times a second. Mark scheme (5 marks). C1: B = µ₀I/2πr. C1: conversion. B1: comparison. B1: alternating current gives alternating field. A1: B = 6.0 µT.', 5),
('add6b54a-29da-5a8a-a4b2-cf7518d1ec7b', '451c0a56-584e-41c1-958b-7b940530308c', '97b06d01-998b-5bf4-8645-77d648f0a328', 'a-level', '24.1', '9702 coursebook 24.1 · Magnetic fields due to currents', 50, 50, 'Two long parallel wires, 0.20 m apart, carry 5.0 A each in opposite directions. Point P lies on the line through both wires, 0.10 m outside wire 1 (so 0.30 m from wire 2). (a) Calculate the flux density at P due to each wire, using B = µ₀I/2πr. (b) Explain whether the two fields add or subtract at P. (c) Calculate the resultant flux density at P, in µT. Give only the answer to (c). Take µ₀/2π = 2.0 × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '6.667 uT', 'µT', false, NULL, false, NULL, '(a) B₁ = 2.0 × 10⁻⁷ × 5.0 ÷ 0.10 = 1.0 × 10⁻⁵ T; B₂ = 2.0 × 10⁻⁷ × 5.0 ÷ 0.30 = 3.33 × 10⁻⁶ T. (b) Outside the pair, opposite currents give opposite field directions, so they subtract. (c) B = 1.0 × 10⁻⁵ − 3.333 × 10⁻⁶ = 6.67 × 10⁻⁶ T. In µT: 6.667 × 10⁻⁶ × 10⁶ = 6.67. Mark scheme (6 marks). C1: B₁. C1: B₂. B1: fields opposite outside the pair. M1: subtract. C1: conversion. A1: B = 6.67 µT.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('4d5ca7d9-d55d-58a8-91a4-fc7d5460b5bf', '584476ca-e9d2-587f-827b-aaf1a908880d', 'The circles get closer together, showing a stronger field', 'A', false, 0),
('0bcfdea6-35cf-53e2-9707-778101a7b438', '584476ca-e9d2-587f-827b-aaf1a908880d', 'The spacing stays the same', 'B', false, 1),
('42b16389-5f95-5d93-9fbc-7b3fabea5b09', '584476ca-e9d2-587f-827b-aaf1a908880d', 'The circles get further apart, showing a weaker field', 'C', true, 2),
('11f87f82-b2b5-50e8-8966-e1e361b8d5ea', '584476ca-e9d2-587f-827b-aaf1a908880d', 'The lines become straight', 'D', false, 3),
('496442e2-f34c-518a-b2e0-f503ebc4d84e', 'a6a6193a-9bef-5900-97cb-9b1646c89b78', 'Curl the fingers in the direction of the current in the turns; the thumb points to the north-pole end', 'A', true, 0),
('1d9ee950-be89-53a0-b550-9dbdf839a6e7', 'a6a6193a-9bef-5900-97cb-9b1646c89b78', 'Point the thumb along the current; the fingers point to the south pole', 'B', false, 1),
('77baecd5-80b9-5547-9e2b-2abf3b385637', 'a6a6193a-9bef-5900-97cb-9b1646c89b78', 'Point the fingers along the field; the thumb gives the force', 'C', false, 2),
('f076c496-23d7-5a44-baad-c8d7a019cef5', 'a6a6193a-9bef-5900-97cb-9b1646c89b78', 'Curl the fingers along the field; the thumb gives the current', 'D', false, 3),
('aa626076-b809-501f-879d-2c5b3df45ca1', '509c9bb5-2d25-5950-bc01-3de9dadc4506', 'The field disappears', 'A', false, 0),
('903e08c6-9be8-5014-b967-2c24382e488c', '509c9bb5-2d25-5950-bc01-3de9dadc4506', 'The field becomes stronger', 'B', false, 1),
('37213df9-d280-56ef-a7b8-e8dfeba02cea', '509c9bb5-2d25-5950-bc01-3de9dadc4506', 'The circles become straight lines', 'C', false, 2),
('f8627fb4-9d94-5879-ae04-df94a5d23f58', '509c9bb5-2d25-5950-bc01-3de9dadc4506', 'The field direction reverses but its pattern stays the same', 'D', true, 3),
('90f7efdb-a521-5aa0-aec0-bafaf392a33c', '934b2fd0-d050-5fae-a5ac-ea8b187be2c7', 'It reduces the current', 'A', false, 0),
('aab5ab5c-f133-5966-ac5b-8d674d4f7dd0', '934b2fd0-d050-5fae-a5ac-ea8b187be2c7', 'It makes the magnetic field very much stronger', 'B', true, 1),
('f91d62b4-a453-589b-b208-8b6c1350bc76', '934b2fd0-d050-5fae-a5ac-ea8b187be2c7', 'It makes the field permanent', 'C', false, 2),
('53ff0d6e-3046-5b1f-9e6a-2d22f2486426', '934b2fd0-d050-5fae-a5ac-ea8b187be2c7', 'It stops the field reversing', 'D', false, 3),
('3bc2c87e-a464-57f9-b875-d1f715baf945', 'd1ef4a8d-b684-5114-9cef-ab5ce802187d', 'In the plane of the coil, along a diameter', 'A', false, 0),
('c7ee5332-c1ad-51a4-ab98-177a07f68908', 'd1ef4a8d-b684-5114-9cef-ab5ce802187d', 'Around the wire in circles only', 'B', false, 1),
('dd6bd278-77e7-5207-aefc-901d21e81f2e', 'd1ef4a8d-b684-5114-9cef-ab5ce802187d', 'Perpendicular to the plane of the coil', 'C', true, 2),
('d86705b5-483c-5a79-88f1-19c425b7c8ff', 'd1ef4a8d-b684-5114-9cef-ab5ce802187d', 'There is no field at the centre', 'D', false, 3),
('edfa5597-cd60-54cd-9354-d75e1282172a', 'f59ea6d2-36bb-5abc-a1ce-50e260e66ce8', 'Its field can be switched off and its strength changed by changing the current', 'A', true, 0),
('64cc0ab6-e8fd-583b-a369-feb27d3918f0', 'f59ea6d2-36bb-5abc-a1ce-50e260e66ce8', 'It never needs a power supply', 'B', false, 1),
('a4b39ace-6adb-52d9-9b77-71e72aac170a', 'f59ea6d2-36bb-5abc-a1ce-50e260e66ce8', 'It is always stronger', 'C', false, 2),
('ab2f21a9-db4d-51b9-8b67-d6c59f76fdcc', 'f59ea6d2-36bb-5abc-a1ce-50e260e66ce8', 'It works without a core', 'D', false, 3),
('e517297d-0f71-5565-a9ed-c914a088b903', 'd7baec58-a495-5a89-a826-c4372b741a14', 'South', 'A', false, 0),
