('9116877d-c0cf-591a-92fe-ca6bebad9d2b', 'd7baec58-a495-5a89-a826-c4372b741a14', 'It depends on the length of the solenoid', 'C', false, 2),
('8253e783-307e-59d6-bde8-e3f40b836d92', 'd7baec58-a495-5a89-a826-c4372b741a14', 'North', 'D', true, 3),
('65d96e1e-728a-57e2-aa2e-a9997ae915ba', 'feccef9c-d327-578d-a365-3c0dd7e6c422', 'Just outside the middle of the solenoid', 'A', false, 0),
('82c3b1a6-0be4-53f3-b97c-9db087424579', 'feccef9c-d327-578d-a365-3c0dd7e6c422', 'Inside the solenoid, away from its ends', 'B', true, 1),
('f8bcd6e3-0f0b-5a33-a3ba-6c17d62e74ee', 'feccef9c-d327-578d-a365-3c0dd7e6c422', 'Far from the solenoid', 'C', false, 2),
('bc9559dd-9715-508c-b1ad-954729adf842', 'feccef9c-d327-578d-a365-3c0dd7e6c422', 'At the centre of each turn of wire only', 'D', false, 3),
('eea8ecec-aa7f-5b0a-9f0c-622045afd618', '4390532a-c063-5597-9111-6fbcecb9e45d', 'From the south pole to the north pole', 'A', false, 0),
('74241666-4d54-51b1-b8c8-0afb40c728a4', '4390532a-c063-5597-9111-6fbcecb9e45d', 'Towards both poles', 'B', false, 1),
('d0931dd9-3413-52ac-a594-1cdb18c78ba5', '4390532a-c063-5597-9111-6fbcecb9e45d', 'From the north pole to the south pole', 'C', true, 2),
('0cd49a69-9232-5945-9bd4-7751e53638c1', '4390532a-c063-5597-9111-6fbcecb9e45d', 'Away from both poles', 'D', false, 3),
('75165368-707f-5f0d-adcf-ee0601f61a72', '3c666571-e3d4-53a5-ac2b-a287ef926c33', 'Zero, because the two fields are equal and opposite there', 'A', true, 0),
('f0bea62e-b7f6-5c0f-a3dd-7857f55280c6', '3c666571-e3d4-53a5-ac2b-a287ef926c33', 'Twice the field of one wire', 'B', false, 1),
('737258a6-f4c1-5632-a436-31baa8a32c1d', '3c666571-e3d4-53a5-ac2b-a287ef926c33', 'The same as the field of one wire', 'C', false, 2),
('00d5bf6c-f777-57e0-97e2-a7fe92c20f28', '3c666571-e3d4-53a5-ac2b-a287ef926c33', 'It points along the wires', 'D', false, 3),
('cb840926-7daa-555e-8ee5-773d7a6b5098', '211152d0-d74b-56db-881a-608f701b44f8', 'It doubles', 'A', false, 0),
('28e7bf55-c507-566e-a012-1efaeda4f9db', '211152d0-d74b-56db-881a-608f701b44f8', 'It stays the same', 'B', false, 1),
('ce3d72a7-4de7-547d-91a1-fa3dbccca3b9', '211152d0-d74b-56db-881a-608f701b44f8', 'It quarters', 'C', false, 2),
('87cada21-3d13-596d-a08f-963efe8516a8', '211152d0-d74b-56db-881a-608f701b44f8', 'It halves', 'D', true, 3),
('32e04575-2bdd-5877-b693-0f886ee8c441', '5336d2ca-112a-5639-afd2-7b443c88acea', 'A long straight wire', 'A', false, 0),
('8b0be002-9c3b-57db-9620-76697aaa39b1', '5336d2ca-112a-5639-afd2-7b443c88acea', 'A short bar magnet', 'B', true, 1),
('1e3f1fc9-362a-55db-9e7e-279bc14bcf16', '5336d2ca-112a-5639-afd2-7b443c88acea', 'Two like poles facing each other', 'C', false, 2),
('1cd79305-df4d-54ff-a32c-222e1ac4c797', '5336d2ca-112a-5639-afd2-7b443c88acea', 'A uniform field', 'D', false, 3),
('8990abb3-5af8-5c65-893f-ddf7943892d9', 'c46075c0-293d-5504-9e32-05578dd096bd', 'East of the wire', 'A', false, 0),
('70fb58c9-a7f1-5211-9cd9-1ec58fde5a07', 'c46075c0-293d-5504-9e32-05578dd096bd', 'North of the wire', 'B', false, 1),
('6fb24c0a-a403-5ebb-a865-024c89615a96', 'c46075c0-293d-5504-9e32-05578dd096bd', 'West of the wire', 'C', true, 2),
('d92c98c1-f530-5f0a-bbf4-7b4627e0244c', 'c46075c0-293d-5504-9e32-05578dd096bd', 'South of the wire', 'D', false, 3),
('d210b447-2eb6-5c9c-bba6-b1eb5ffdef4a', '114227b6-5b5d-57d2-86b4-7b2e1076e02b', 'Due south', 'A', true, 0),
('2c1eb79f-3213-50b6-a187-9a5f1ef6e895', '114227b6-5b5d-57d2-86b4-7b2e1076e02b', 'Due north', 'B', false, 1),
('e4b89d75-afbc-57ee-af3f-8d7eba679d9a', '114227b6-5b5d-57d2-86b4-7b2e1076e02b', 'Vertically upwards', 'C', false, 2),
('87dec063-8eec-5e69-a5b0-f6077f67183b', '114227b6-5b5d-57d2-86b4-7b2e1076e02b', 'Due east', 'D', false, 3),
('f89c4382-d53f-59fb-962b-e762fa0f0291', 'b708e987-b813-5f68-af30-2c8a34b01068', 'Increasing the current', 'A', false, 0),
('50263433-ca16-504b-b84a-fb7eb3c08fba', 'b708e987-b813-5f68-af30-2c8a34b01068', 'Adding more turns per metre', 'B', false, 1),
('3cbe32b6-c921-551e-add7-6e91d7d39716', 'b708e987-b813-5f68-af30-2c8a34b01068', 'Using a soft iron core instead of air', 'C', false, 2),
('0dde9b48-f9fc-5639-bbd0-a3192e8622bb', 'b708e987-b813-5f68-af30-2c8a34b01068', 'Replacing the iron core with a copper core', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('6bed934e-7287-52ee-b62c-b242400c731a', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 9, 9, 'In Fleming''s left-hand rule, what does the second finger represent?', NULL, 1, 'multiple_choice'::answer_type, 'The conventional current', NULL, false, NULL, false, NULL, 'First finger: Field; seCond finger: Current; thuMb: Motion (force). Mark scheme (1 mark). B1: C (The conventional current).', 1),
('cbc829c4-76c3-5b2f-880a-87e0706a7f70', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 10, 10, 'A 0.050 m length of wire carrying 2.5 A lies at right angles to a uniform field of 0.80 T. Calculate the force on it.', NULL, 1, 'numeric'::answer_type, '0.1', 'N', false, NULL, false, NULL, 'F = BIL = 0.80 × 2.5 × 0.050 = 0.10 N. Mark scheme (2 marks). C1: F = BIL. A1: F = 0.10 N.', 2),
('e4851367-792c-55a7-b67a-ba9dff51df11', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 11, 11, 'For a given current and field, when is the force on a straight wire in a magnetic field greatest?', NULL, 1, 'multiple_choice'::answer_type, 'When the wire is at right angles to the field', NULL, false, NULL, false, NULL, 'F = BIL sin θ is largest when θ = 90°. Mark scheme (1 mark). B1: A (When the wire is at right angles to the field).', 1),
('7e55e119-24b6-5978-b23c-8ff91a5b50b4', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 12, 12, 'A 0.15 m wire lies at right angles to a 0.20 T field and experiences a force of 0.045 N. Calculate the current in the wire.', NULL, 1, 'numeric'::answer_type, '1.5', 'A', false, NULL, false, NULL, 'I = F/(BL) = 0.045 ÷ (0.20 × 0.15) = 1.5 A. Mark scheme (2 marks). C1: I = F/(BL). A1: I = 1.5 A.', 2),
('cffedf14-34cd-55b5-946f-8358a5103694', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 13, 13, 'A horizontal wire carries a current due north in a magnetic field that points vertically downwards. In which direction is the force on the wire?', NULL, 1, 'multiple_choice'::answer_type, 'Due west', NULL, false, NULL, false, NULL, 'Fleming''s left-hand rule: first finger down, second finger north, thumb points west. Mark scheme (1 mark). B1: D (Due west).', 1),
('5c24bf85-18cf-5e2f-afc7-3d6f58d767a3', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 14, 14, 'A 0.30 m wire carrying 2.0 A lies at 60° to a uniform field of 0.50 T. Calculate the force on it.', NULL, 1, 'numeric'::answer_type, '0.2598', 'N', false, NULL, false, NULL, 'F = BIL sin θ = 0.50 × 2.0 × 0.30 × sin 60° = 0.260 N. Mark scheme (2 marks). C1: F = BIL sin θ. A1: F = 0.260 N.', 2),
('becd76ef-4f3c-5930-8f08-9bf2cf040a53', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 15, 15, 'Which change would double the force on a current-carrying wire at right angles to a uniform field?', NULL, 1, 'multiple_choice'::answer_type, 'Doubling the current', NULL, false, NULL, false, NULL, 'F = BIL, so with B and L fixed the force is proportional to the current. Mark scheme (1 mark). B1: B (Doubling the current).', 1),
('b90d7e81-c2ad-5aef-8e8e-7af2c769e164', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 16, 16, 'A power cable carries 500 A at right angles to the Earth''s magnetic field of 5.0 × 10⁻⁵ T. Calculate the force on each metre of cable.', NULL, 1, 'numeric'::answer_type, '0.025', 'N m⁻¹', false, NULL, false, NULL, 'F/L = BI = 5.0 × 10⁻⁵ × 500 = 0.025 N m⁻¹. Mark scheme (2 marks). C1: F/L = BI. A1: F/L = 0.025 N m⁻¹.', 2),
('d7917509-9707-5291-8a1e-4da6897a61e7', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 17, 17, 'Why does a current-carrying coil in a magnetic field rotate?', NULL, 1, 'multiple_choice'::answer_type, 'The forces on opposite sides are equal and opposite but along different lines, forming a couple', NULL, false, NULL, false, NULL, 'Opposite currents in the two sides give opposite forces, producing a turning effect. Mark scheme (1 mark). B1: C (The forces on opposite sides are equal and opposite but along different lines, forming a couple).', 1),
('8a4986ff-0c11-55eb-829d-b4ccb7077802', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 18, 18, 'In a school motor kit, a 0.020 m section of wire carrying 3.0 A at right angles to the field between the magnets feels a force of 0.012 N. What is the flux density?', NULL, 1, 'numeric'::answer_type, '0.2', 'T', false, NULL, false, NULL, 'B = F/(IL) = 0.012 ÷ (3.0 × 0.020) = 0.20 T. Mark scheme (2 marks). C1: B = F/(IL). A1: B = 0.20 T.', 2),
('5a7dc059-820a-5cfb-bfc7-861523657000', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 19, 19, 'Only the current in a wire in a magnetic field is reversed. What happens to the force on the wire?', NULL, 1, 'multiple_choice'::answer_type, 'It reverses direction', NULL, false, NULL, false, NULL, 'The force direction depends on the current direction (left-hand rule). Mark scheme (1 mark). B1: A (It reverses direction).', 1),
('0e75f1d5-ca67-5698-9e63-550da1c1c7e8', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 20, 20, 'Calculate the force on a 4.0 cm length of wire carrying 8.0 A at right angles to a field of 0.15 T.', NULL, 1, 'numeric'::answer_type, '0.048', 'N', false, NULL, false, NULL, 'F = BIL = 0.15 × 8.0 × 0.040 = 0.048 N. Mark scheme (2 marks). C1: F = BIL with L in m. A1: F = 0.048 N.', 2),
('77548820-965b-560a-ae49-fb1be3a0a1cd', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 21, 21, 'Why does a current-carrying wire lying along the field lines feel no force?', NULL, 1, 'multiple_choice'::answer_type, 'The force depends on sin θ, and θ = 0 when the wire is parallel to the field', NULL, false, NULL, false, NULL, 'F = BIL sin θ = 0 when θ = 0. Mark scheme (1 mark). B1: D (The force depends on sin θ, and θ = 0 when the wire is parallel to the field).', 1),
('81eb9c33-f190-5937-8779-2a22457e3095', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 22, 22, 'Between the poles of a 60 mT magnet, 0.10 m of a lead carrying 0.50 A crosses the field at right angles. Find the force on it, in mN.', NULL, 1, 'numeric'::answer_type, '3 mN', 'mN', false, NULL, false, NULL, 'F = BIL = 60 × 10⁻³ × 0.50 × 0.10 = 3.0 × 10⁻³ N. In mN: 3.0 × 10⁻³ × 1000 = 3.0. Mark scheme (2 marks). C1: F = BIL with B in T. A1: F = 3.0 mN.', 2),
('758b5e4b-783e-5ae1-97d2-72a81758fa5c', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 23, 23, 'In a "catapult field" diagram, why is a current-carrying wire pushed sideways?', NULL, 1, 'multiple_choice'::answer_type, 'Its circular field adds to the uniform field on one side and cancels it on the other; the wire is pushed towards the weaker side', NULL, false, NULL, false, NULL, 'The combined field is strong on one side and weak on the other, like a stretched catapult. Mark scheme (1 mark). B1: B (Its circular field adds to the uniform field on one side and cancels it on the other; the wire is pushed towards the weaker side).', 1),
('f9f2cbc1-a5df-52b0-9be2-60c983dec734', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 24, 24, 'A wire at right angles to a field feels a force of 0.20 N. What force does it feel when turned to 30° to the field?', NULL, 1, 'numeric'::answer_type, '0.1', 'N', false, NULL, false, NULL, 'F ∝ sin θ, so F = 0.20 × sin 30° = 0.10 N. Mark scheme (1 mark). A1: F = 0.10 N.', 1),
('13614f84-5c7c-58af-8575-250330e9e3a0', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 25, 25, 'A straight wire in a uniform field feels a force of 0.10 N when perpendicular to the field. At what angle to the field must it be placed to feel a force of 0.050 N?', NULL, 2, 'numeric'::answer_type, '30', '°', false, NULL, false, NULL, 'sin θ = 0.050 ÷ 0.10 = 0.50, so θ = sin⁻¹ 0.50 = 30°. Mark scheme (3 marks). C1: F = F_max sin θ. C1: inverse sine. A1: θ = 30°.', 3),
('c2f39369-c416-50ee-b457-af9e3bccaa66', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 26, 26, 'A loudspeaker coil has 50 turns of radius 1.5 cm in a radial magnetic field of 0.80 T, which is at right angles to the wire everywhere. Calculate the force on the coil when the current is 0.20 A.', NULL, 2, 'numeric'::answer_type, '0.754', 'N', false, NULL, false, NULL, 'Total length L = 50 × 2π × 0.015 = 4.71 m. F = BIL = 0.80 × 0.20 × 4.712 = 0.754 N. Mark scheme (3 marks). C1: total length of wire. C1: F = BIL. A1: F = 0.754 N.', 3),
('34df32b7-b405-5f6c-bcfe-2dfd6bc264cd', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 27, 27, 'A beam of electrons travels east through a magnetic field. To apply Fleming''s left-hand rule, which way should the second finger point?', NULL, 2, 'multiple_choice'::answer_type, 'West, because conventional current is opposite to electron flow', NULL, false, NULL, false, NULL, 'The rule uses conventional current, which flows opposite to the electrons. Mark scheme (3 marks). C1: conventional current. C1: opposite to electron motion. A1: C (West, because conventional current is opposite to electron flow).', 3),
('69d1e122-0bd4-54b5-adf2-270838b0c86b', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 28, 28, 'A horizontal copper wire with a mass of 0.020 kg per metre lies at right angles to a horizontal magnetic field of 0.25 T. Calculate the current needed for the magnetic force to support its weight. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.7848', 'A', false, NULL, false, NULL, 'For each metre, BIL = mg: I = mg/(BL) = 0.020 × 9.81 ÷ (0.25 × 1.0) = 0.785 A. Mark scheme (4 marks). M1: magnetic force = weight. C1: per metre. C1: substitution. A1: I = 0.785 A.', 4),
('4dd59a3b-61b7-519a-b762-e679753c5b92', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 29, 29, 'A rectangular coil of 20 turns has sides of length 0.050 m at right angles to a 0.40 T field. The coil carries 1.5 A. Calculate the force on one of these sides.', NULL, 2, 'numeric'::answer_type, '0.6', 'N', false, NULL, false, NULL, 'F = NBIL = 20 × 0.40 × 1.5 × 0.050 = 0.60 N. Mark scheme (3 marks). C1: force on each turn. C1: × number of turns. A1: F = 0.60 N.', 3),
('5a48818e-b624-551b-9fe4-2d35b827ddcc', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 30, 30, 'The two 0.050 m sides of a 20-turn coil each feel a force of 0.60 N in opposite directions. The sides are 0.040 m apart. Calculate the torque on the coil.', NULL, 2, 'numeric'::answer_type, '0.024', 'N m', false, NULL, false, NULL, 'Torque of a couple = one force × perpendicular separation = 0.60 × 0.040 = 0.024 N m. Mark scheme (4 marks). M1: forces form a couple. C1: torque = F × d. C1: substitution. A1: torque = 0.024 N m.', 4),
('e27ad5e4-ea84-5576-8d3c-b3d58a745ebb', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 31, 31, 'Why does a simple d.c. motor need a split-ring commutator?', NULL, 2, 'multiple_choice'::answer_type, 'It reverses the current in the coil every half turn, so the couple keeps turning the coil the same way', NULL, false, NULL, false, NULL, 'Without it, the forces would reverse their turning effect after half a revolution. Mark scheme (3 marks). C1: reverses current each half-turn. C1: maintains rotation direction. A1: A (It reverses the current in the coil every half turn, so the couple keeps turning the coil the same way).', 3),
('1c68d7ee-a77b-54bb-8d9c-fc3cc2e382b2', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 32, 32, 'A metal rod of mass 0.010 kg rests across two horizontal rails 0.080 m apart. A current of 5.0 A flows through it, and a vertical field of 0.30 T acts. Ignoring friction, calculate the acceleration of the rod.', NULL, 2, 'numeric'::answer_type, '12', 'm s⁻²', false, NULL, false, NULL, 'F = BIL = 0.30 × 5.0 × 0.080 = 0.12 N. a = F/m = 0.12 ÷ 0.010 = 12 m s⁻². Mark scheme (3 marks). C1: F = BIL. C1: a = F/m. A1: a = 12 m s⁻².', 3),
('e3ba2040-da2b-5842-ba6e-00061fed3307', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 33, 33, 'A wire is at an angle θ to a uniform magnetic field. Which component of the field produces the force on the wire?', NULL, 2, 'multiple_choice'::answer_type, 'The component perpendicular to the wire, B sin θ', NULL, false, NULL, false, NULL, 'The parallel component exerts no force, so F = (B sin θ)IL. Mark scheme (3 marks). C1: perpendicular component. C1: B sin θ. A1: D (The component perpendicular to the wire, B sin θ).', 3),
('faf8dbc2-5022-547f-87f5-9fb277637648', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 34, 34, 'A 50 m span of overhead cable carries 300 A at 40° to the Earth''s field of 4.0 × 10⁻⁵ T. Calculate the force on the span.', NULL, 2, 'numeric'::answer_type, '0.3857', 'N', false, NULL, false, NULL, 'F = BIL sin θ = 4.0 × 10⁻⁵ × 300 × 50 × sin 40° = 0.386 N. Mark scheme (3 marks). C1: F = BIL sin θ. C1: substitution. A1: F = 0.386 N.', 3),
('94dac86f-e233-5b43-a99c-c50a146977b0', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 35, 35, 'On a diagram, a uniform field points from left to right across the page, and a wire carries a current into the page. In which direction is the force on the wire?', NULL, 2, 'multiple_choice'::answer_type, 'Towards the bottom of the page', NULL, false, NULL, false, NULL, 'Left-hand rule: first finger right, second finger into the page, thumb points down the page. Mark scheme (4 marks). C1: field right. C1: current into page. C1: thumb down. A1: B (Towards the bottom of the page).', 4),
('1be859ca-4d21-59fb-8aad-2cc8e708e0f5', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 36, 36, 'A 0.050 m length of wire at right angles to a 0.10 T field experiences a force of 2.5 mN. Calculate the current.', NULL, 2, 'numeric'::answer_type, '0.5', 'A', false, NULL, false, NULL, 'I = F/(BL) = 2.5 × 10⁻³ ÷ (0.10 × 0.050) = 0.50 A. Mark scheme (3 marks). C1: force in N. C1: I = F/(BL). A1: I = 0.50 A.', 3),
('6a1c825a-b242-50d3-a1c9-225541248e15', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 37, 37, 'A straight wire 0.40 m long carries 2.0 A at right angles to a field of 0.30 T, but only half of its length lies inside the field. Calculate the force on the wire.', NULL, 2, 'numeric'::answer_type, '0.12', 'N', false, NULL, false, NULL, 'Only the length in the field counts: L = 0.20 m. F = BIL = 0.30 × 2.0 × 0.20 = 0.12 N. Mark scheme (4 marks). B1: only length in field. C1: L = 0.20 m. C1: F = BIL. A1: F = 0.12 N.', 4),
('30be3c9b-166f-51fe-ba5d-c04ecbdc8ffc', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 38, 38, 'A wire at right angles to a field is turned until it is at 45° to the field. By what factor does the force change?', NULL, 2, 'multiple_choice'::answer_type, 'It is multiplied by about 0.71', NULL, false, NULL, false, NULL, 'F ∝ sin θ: sin 45° = 0.71. Mark scheme (3 marks). C1: F ∝ sin θ. C1: sin 45°. A1: C (It is multiplied by about 0.71).', 3),
('0655af3e-f39f-500b-9af0-e0c31d31db33', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 39, 39, 'A horizontal copper wire has a mass of 1.0 × 10⁻³ kg per metre and lies at right angles to the Earth''s horizontal field of 5.0 × 10⁻⁵ T. Calculate the current needed for the magnetic force to support the wire. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '196.2', 'A', false, NULL, false, NULL, 'I = mg/(BL) per metre = 1.0 × 10⁻³ × 9.81 ÷ 5.0 × 10⁻⁵ = 196 A: far too large for such a thin wire. Mark scheme (3 marks). M1: BIL = mg. C1: substitution. A1: I = 196 A.', 3),
('c0578d20-bd29-5650-8f18-18c68441a41a', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 40, 40, 'A horizontal wire 0.050 m long and of mass 3.0 g hangs from two light vertical conductors in a vertical magnetic field of 0.20 T. A current of 2.0 A is passed through it, and the wire swings sideways until the conductors make an angle θ with the vertical. (a) Calculate the magnetic force on the wire. (b) Calculate its weight. (c) Calculate θ. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '34.2', '°', false, NULL, false, NULL, '(a) F = BIL = 0.20 × 2.0 × 0.050 = 0.020 N, horizontal. (b) W = 3.0 × 10⁻³ × 9.81 = 0.0294 N. (c) tan θ = F/W = 0.020 ÷ 0.02943 = 0.6796, so θ = tan⁻¹ 0.6796 = 34.2°. Mark scheme (6 marks). C1: F = BIL. C1: weight in N. M1: tan θ = F/W. C1: substitution. B1: force horizontal, perpendicular to field. A1: θ = 34.2°.', 6),
('5bf40f87-8843-543d-b30e-ec9fd1069ec9', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 41, 41, 'A rectangular coil of 100 turns, 0.040 m long and 0.030 m wide, carries 0.25 A. The 0.040 m sides are at right angles to a uniform field of 0.15 T. (a) Calculate the force on each 0.040 m side. (b) Calculate the maximum torque on the coil. (c) State the position of the coil when the torque is a maximum. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.0045', 'N m', false, NULL, false, NULL, '(a) F = NBIL = 100 × 0.15 × 0.25 × 0.040 = 0.15 N. (b) Maximum torque = F × width = 0.15 × 0.030 = 4.5 × 10⁻³ N m. (c) When the plane of the coil is parallel to the field, so the forces are furthest apart. Mark scheme (5 marks). C1: F = NBIL. M1: couple. C1: torque = F × d. B1: plane parallel to field. A1: torque = 0.0045 N m.', 5),
('c9ad1c49-db47-51aa-9268-7b4c35c56d83', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 42, 42, 'In a model rail gun, a rod of mass 0.020 kg lies across two rails 0.10 m apart in a vertical field of 0.50 T. A current of 4.0 A flows through the rod, and a friction force of 0.050 N opposes its motion. (a) Calculate the magnetic force on the rod. (b) Calculate the acceleration. (c) Calculate its speed after moving 0.80 m from rest. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '3.464', 'm s⁻¹', false, NULL, false, NULL, '(a) F = BIL = 0.50 × 4.0 × 0.10 = 0.20 N. (b) a = (0.20 − 0.050) ÷ 0.020 = 7.5 m s⁻². (c) v = √(2as) = √(2 × 7.5 × 0.80) = 3.46 m s⁻¹. Mark scheme (6 marks). C1: F = BIL. C1: resultant force. C1: a = F/m. M1: v² = 2as. C1: substitution. A1: v = 3.46 m s⁻¹.', 6),
('7febbe95-1cb8-5d60-bb20-8ac8868887c6', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 43, 43, 'A 0.50 m wire lies along the x-axis carrying 3.0 A in the +x direction. A uniform field of 0.40 T lies in the x–y plane at 30° to the x-axis. (a) Calculate the force on the wire and state its direction. (b) The wire is turned to lie along the y-axis. Calculate the new force. (c) State an orientation of the wire, in the x–y plane, that gives zero force. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.5196', 'N', false, NULL, false, NULL, '(a) F = 0.40 × 3.0 × 0.50 × sin 30° = 0.30 N, along the z-axis (perpendicular to both wire and field). (b) The angle between wire and field is now 60°: F = 0.40 × 3.0 × 0.50 × sin 60° = 0.520 N. (c) Along the field direction, at 30° to the x-axis. Mark scheme (5 marks). C1: F = BIL sin 30°. B1: direction perpendicular to both. C1: angle now 60°. B1: parallel gives zero. A1: F = 0.520 N.', 5),
('3e9846e9-5556-52e9-8aa3-658d9f2a8b50', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 44, 44, 'An electromagnetic pump moves liquid sodium along a channel 0.050 m wide and 0.020 m high. A current of 200 A passes across the 0.050 m width, at right angles to both the flow and a magnetic field of 0.30 T. (a) Calculate the force on the sodium in the field region. (b) Calculate the pressure difference this produces along the channel. (c) Explain why this pump has no moving parts. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3000', 'Pa', false, NULL, false, NULL, '(a) F = BIL = 0.30 × 200 × 0.050 = 3.0 N. (b) The force acts over the channel cross-section 0.050 × 0.020 = 1.0 × 10⁻³ m², so p = 3.0 ÷ 1.0 × 10⁻³ = 3.0 × 10³ Pa. (c) The liquid metal itself carries the current, so the magnetic force acts directly on the fluid. Mark scheme (6 marks). C1: F = BIL. C1: cross-sectional area. M1: p = F/A. C1: value. B1: force acts on the conducting liquid. A1: p = 3000 Pa.', 6),
('96bcf4ed-2878-53cb-966a-eed376b3aff0', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 45, 45, 'A loudspeaker coil of 80 turns and diameter 2.5 cm sits in a radial field of 1.2 T, at right angles to the wire everywhere. (a) Calculate the total length of wire in the field. (b) Calculate the force on the coil when the current is 0.50 A. (c) The coil and cone have a combined mass of 10 g. Calculate their acceleration, ignoring other forces. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3.77', 'N', false, NULL, false, NULL, '(a) L = 80 × π × 0.025 = 6.28 m. (b) F = BIL = 1.2 × 0.50 × 6.283 = 3.77 N. (c) a = F/m = 3.770 ÷ 0.010 = 377 m s⁻². Mark scheme (5 marks). C1: circumference × turns. C1: F = BIL. C1: a = F/m. B1: mass in kg. A1: F = 3.77 N.', 5),
('5b6ba985-e678-54ff-b9eb-3f37fa2611b3', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 46, 46, 'A student measures the force on a 0.040 m length of wire at right angles to a magnetic field for different currents: I/A = 1.0, 2.0, 3.0, 4.0 and F/mN = 2.4, 4.9, 7.2, 9.7. (a) Describe the relationship between F and I. (b) Calculate the gradient of the F–I graph using the first and last readings. (c) Calculate the flux density, in mT. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '60.83 mT', 'mT', false, NULL, false, NULL, '(a) F ∝ I: a straight line through the origin. (b) Gradient = (9.7 − 2.4) × 10⁻³ ÷ (4.0 − 1.0) = 0.00243 N A⁻¹. (c) Gradient = BL, so B = 0.002433 ÷ 0.040 = 0.0608 T. In mT: 0.06083 × 1000 = 60.8. Mark scheme (6 marks). B1: F ∝ I. C1: gradient. M1: gradient = BL. C1: B. C1: conversion. A1: B = 60.8 mT.', 6),
('37de28a1-7f6b-5add-bf07-ba23d98befb6', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 47, 47, 'A square coil of 50 turns and side 0.060 m carries 1.2 A in a uniform field of 0.20 T. (a) Show that the maximum torque is NBIA. (b) Calculate the maximum torque. (c) State the torque when the plane of the coil is perpendicular to the field, and explain. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.0432', 'N m', false, NULL, false, NULL, '(a) Each side of length a feels NBIa; the couple arm is a, so torque = NBIa × a = NBIA. (b) Torque = 50 × 0.20 × 1.2 × 0.060² = 0.0432 N m. (c) Zero: the forces on opposite sides then act along the same line. Mark scheme (5 marks). M1: force on side × arm. B1: NBIA shown. C1: substitution. B1: zero torque, forces in line. A1: torque = 0.0432 N m.', 5),
('d6954bd4-5507-5cdc-a935-3a81b5a406df', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 48, 48, 'A copper rod 0.30 m long and of mass 0.045 kg hangs horizontally from two springs, at right angles to a horizontal magnetic field of 0.60 T. (a) State the direction of the magnetic force needed to remove the tension in the springs. (b) Calculate the current needed. (c) Explain what happens to the springs if the current is reversed. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '2.453', 'A', false, NULL, false, NULL, '(a) Vertically upwards, to balance the weight. (b) BIL = mg, so I = 0.045 × 9.81 ÷ (0.60 × 0.30) = 2.45 A. (c) The force reverses and acts downwards, so the springs stretch further, with tension 2mg in total. Mark scheme (6 marks). B1: upward force. M1: BIL = mg. C1: substitution. C1: value. B1: springs stretch more. A1: I = 2.45 A.', 6),
('cd387421-9a2d-5693-8263-05f64685d9f0', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 49, 49, 'A wire is bent into a semicircle of radius 0.10 m and placed in a uniform field of 0.50 T at right angles to the plane of the semicircle. A current of 2.0 A flows in it. (a) Explain why the resultant force on the semicircle equals the force on a straight wire joining its ends. (b) Calculate this resultant force. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.2', 'N', false, NULL, false, NULL, '(a) The force on each small element is perpendicular to it; adding them, the components along the diameter cancel and the rest add to the force on the straight chord. (b) F = BI × 2r = 0.50 × 2.0 × 0.20 = 0.20 N. Mark scheme (5 marks). B1: components cancel by symmetry. M1: effective length = diameter. C1: F = BIL. C1: value. A1: F = 0.20 N.', 5),
('ba425c5f-f755-503b-b695-49dcd9173f79', '451c0a56-584e-41c1-958b-7b940530308c', '58c686dd-7b6b-5113-bac6-799f7572dda5', 'a-level', '24.2', '9702 coursebook 24.2 · Force on a current-carrying conductor', 50, 50, 'A horizontal wire 2.0 m long carrying 50 A from east to west experiences a vertical force of 2.0 mN due to the Earth''s field. (a) State which component of the Earth''s field produces this force. (b) Calculate this component, in µT. (c) The wire is turned to run north–south, and the Earth''s vertical component is 4.4 × 10⁻⁵ T. Calculate the new force, in mN. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '20 uT', 'µT', false, NULL, false, NULL, '(a) The horizontal (northward) component, which is at right angles to an east–west wire. (b) B_h = F/(IL) = 2.0 × 10⁻³ ÷ (50 × 2.0) = 2.0 × 10⁻⁵ T. In µT: 2.0 × 10⁻⁵ × 10⁶ = 20. (c) Now only the vertical component is perpendicular to the wire and gives a horizontal force: F = 4.4 × 10⁻⁵ × 50 × 2.0 = 4.4 × 10⁻³ N, which is 4.4 mN. Mark scheme (6 marks). B1: horizontal component. C1: B = F/(IL). C1: conversion. M1: vertical component for N–S wire. C1: new force. A1: B = 20 µT.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('6f759d54-6554-50f3-bc43-7d8bfa9b962a', '6bed934e-7287-52ee-b62c-b242400c731a', 'The magnetic field', 'A', false, 0),
('b1c881cc-4bba-54c7-aece-158754f13d7b', '6bed934e-7287-52ee-b62c-b242400c731a', 'The force (motion)', 'B', false, 1),
('c7f8d44a-3a34-5f90-9d55-230dba25103e', '6bed934e-7287-52ee-b62c-b242400c731a', 'The conventional current', 'C', true, 2),
('54b90b7a-bc99-577e-ab34-60c37e3bd802', '6bed934e-7287-52ee-b62c-b242400c731a', 'The flow of electrons', 'D', false, 3),
('27f369ba-2994-5115-9a25-7c5879c34aa9', 'e4851367-792c-55a7-b67a-ba9dff51df11', 'When the wire is at right angles to the field', 'A', true, 0),
('bd1a697f-5801-52bb-8dc8-0a9ff7ba1e96', 'e4851367-792c-55a7-b67a-ba9dff51df11', 'When the wire is parallel to the field', 'B', false, 1),
('b47c0c56-d8d2-5d41-9538-620dd4993341', 'e4851367-792c-55a7-b67a-ba9dff51df11', 'When the wire is at 45° to the field', 'C', false, 2),
('49752469-b002-5eed-bc3a-c3b468cd5c26', 'e4851367-792c-55a7-b67a-ba9dff51df11', 'The force does not depend on direction', 'D', false, 3),
('c03119c9-4dd5-586a-a7a1-9e0fa495da43', 'cffedf14-34cd-55b5-946f-8358a5103694', 'Due east', 'A', false, 0),
('e23a9473-0bd2-5876-b4fd-2a2499833ac3', 'cffedf14-34cd-55b5-946f-8358a5103694', 'Vertically upwards', 'B', false, 1),
('88d6a4bd-4634-55b9-b69d-c968ef6f4219', 'cffedf14-34cd-55b5-946f-8358a5103694', 'Due south', 'C', false, 2),
('cff6b131-b152-5208-ad29-c66faf3ad860', 'cffedf14-34cd-55b5-946f-8358a5103694', 'Due west', 'D', true, 3),
('607b339e-193e-5918-9c63-5e97ad19d191', 'becd76ef-4f3c-5930-8f08-9bf2cf040a53', 'Halving the length of wire in the field', 'A', false, 0),
('7c43e733-e29a-54a1-87b7-f0634a3710c4', 'becd76ef-4f3c-5930-8f08-9bf2cf040a53', 'Doubling the current', 'B', true, 1),
('4a86f93d-7eac-57b5-a625-e06b3cf4e092', 'becd76ef-4f3c-5930-8f08-9bf2cf040a53', 'Turning the wire to lie along the field', 'C', false, 2),
('1cac03e3-79bf-5cd3-a7da-07159a8f580a', 'becd76ef-4f3c-5930-8f08-9bf2cf040a53', 'Reversing the current', 'D', false, 3),
('b619afcd-3de3-50bf-9f80-c31fd8626e56', 'd7917509-9707-5291-8a1e-4da6897a61e7', 'The field pulls the coil towards the north pole', 'A', false, 0),
('8a18fe52-6cd5-5a08-9bcd-61c048817c56', 'd7917509-9707-5291-8a1e-4da6897a61e7', 'The current heats the coil', 'B', false, 1),
('f3a5d9c6-1a05-5bed-a68d-7a85ec5eb91d', 'd7917509-9707-5291-8a1e-4da6897a61e7', 'The forces on opposite sides are equal and opposite but along different lines, forming a couple', 'C', true, 2),
('5de796c2-8f05-5985-bca1-38e0c5a493a9', 'd7917509-9707-5291-8a1e-4da6897a61e7', 'The coil becomes a permanent magnet', 'D', false, 3),
('4bbcc0da-f57a-5d1a-b937-aa1a4199be10', '5a7dc059-820a-5cfb-bfc7-861523657000', 'It reverses direction', 'A', true, 0),
('03e51260-e83d-5b2c-85f2-97a3d1cf0091', '5a7dc059-820a-5cfb-bfc7-861523657000', 'It doubles', 'B', false, 1),
('98c2ddc1-a80c-5577-92ea-e365f5501954', '5a7dc059-820a-5cfb-bfc7-861523657000', 'It becomes zero', 'C', false, 2),
('c2f8a1f5-2055-5c21-b921-d00d6ec2c0f8', '5a7dc059-820a-5cfb-bfc7-861523657000', 'It stays the same', 'D', false, 3),
('c8bd1344-ffd2-54f6-a4a1-5d7fcf129542', '77548820-965b-560a-ae49-fb1be3a0a1cd', 'The current is too small', 'A', false, 0),
('b9b5acf8-526d-5a7a-865f-c03ae3f780e1', '77548820-965b-560a-ae49-fb1be3a0a1cd', 'Magnetic fields only act on magnets', 'B', false, 1),
('98a88539-9fda-5fea-b30a-6720ef8b5f6a', '77548820-965b-560a-ae49-fb1be3a0a1cd', 'The wire is not magnetic', 'C', false, 2),
('2ef4d2f2-27dc-5904-bdcd-8902d2cd7d20', '77548820-965b-560a-ae49-fb1be3a0a1cd', 'The force depends on sin θ, and θ = 0 when the wire is parallel to the field', 'D', true, 3),
('97f0d55b-0d8e-589f-82ef-d6a7f47cc62e', '758b5e4b-783e-5ae1-97d2-72a81758fa5c', 'The field lines pull the wire towards the stronger side', 'A', false, 0),
('e78821c3-b10e-59ed-b1a7-09022e57264d', '758b5e4b-783e-5ae1-97d2-72a81758fa5c', 'Its circular field adds to the uniform field on one side and cancels it on the other; the wire is pushed towards the weaker side', 'B', true, 1),
('e0a142f0-0a31-5532-aca5-b0d61ee7db37', '758b5e4b-783e-5ae1-97d2-72a81758fa5c', 'The wire is attracted to the north pole', 'C', false, 2),
('b95f9a68-c7f0-55dc-ab7d-5575bd500726', '758b5e4b-783e-5ae1-97d2-72a81758fa5c', 'The field lines pass through the wire', 'D', false, 3),
('12fa45e1-9c32-59bf-b60b-eacbeae30392', '34df32b7-b405-5f6c-bcfe-2dfd6bc264cd', 'East, along the electron beam', 'A', false, 0),
('10af830d-e1b6-5247-a590-0fbb75d04cee', '34df32b7-b405-5f6c-bcfe-2dfd6bc264cd', 'Along the field', 'B', false, 1),
('d1e5e8d0-5287-5b20-a88e-c79c16a9d269', '34df32b7-b405-5f6c-bcfe-2dfd6bc264cd', 'West, because conventional current is opposite to electron flow', 'C', true, 2),
('421cf5bb-443f-58c7-8142-0daa2014becc', '34df32b7-b405-5f6c-bcfe-2dfd6bc264cd', 'Vertically upwards', 'D', false, 3),
('dd8a1016-3f70-5660-ae4e-966356900ccb', 'e27ad5e4-ea84-5576-8d3c-b3d58a745ebb', 'It reverses the current in the coil every half turn, so the couple keeps turning the coil the same way', 'A', true, 0),
('fe420085-0396-536e-a24c-c86359c6592e', 'e27ad5e4-ea84-5576-8d3c-b3d58a745ebb', 'It increases the current', 'B', false, 1),
('87d67df2-ac92-5722-99c2-0a84689ae8c0', 'e27ad5e4-ea84-5576-8d3c-b3d58a745ebb', 'It stops the coil overheating', 'C', false, 2),
('8afa9b67-e919-5673-a2cf-e4efc861c655', 'e27ad5e4-ea84-5576-8d3c-b3d58a745ebb', 'It keeps the field direction constant', 'D', false, 3),
('c2d86034-5eeb-57b5-8f86-defcdce5e00e', 'e3ba2040-da2b-5842-ba6e-00061fed3307', 'The component parallel to the wire, B cos θ', 'A', false, 0),
('759a2758-e2af-5dab-a08d-a181d1238797', 'e3ba2040-da2b-5842-ba6e-00061fed3307', 'Both components equally', 'B', false, 1),
('d05c64e7-8200-5111-9393-125a15daeb91', 'e3ba2040-da2b-5842-ba6e-00061fed3307', 'Neither: only the current matters', 'C', false, 2),
('348bbccf-78a7-5ded-a1e7-9cfa361784b8', 'e3ba2040-da2b-5842-ba6e-00061fed3307', 'The component perpendicular to the wire, B sin θ', 'D', true, 3),
('7d50dc0a-6038-5d5d-9bda-00528ba4f6b5', '94dac86f-e233-5b43-a99c-c50a146977b0', 'Towards the top of the page', 'A', false, 0),
('e8a6f714-0c4f-5485-ae8f-13e3d2409d4f', '94dac86f-e233-5b43-a99c-c50a146977b0', 'Towards the bottom of the page', 'B', true, 1),
('a17cb655-5ab0-5bf0-901c-458626ba835e', '94dac86f-e233-5b43-a99c-c50a146977b0', 'To the right', 'C', false, 2),
('7965b991-d0d1-5f2a-a15f-2eacaa2afade', '94dac86f-e233-5b43-a99c-c50a146977b0', 'Out of the page', 'D', false, 3),
('548383bf-0834-5523-9177-333add31cba8', '30be3c9b-166f-51fe-ba5d-c04ecbdc8ffc', 'It is halved', 'A', false, 0),
('dc36d7a5-38e3-5697-b3a2-722d45f1414c', '30be3c9b-166f-51fe-ba5d-c04ecbdc8ffc', 'It stays the same', 'B', false, 1),
('ffb8d86a-2574-5099-8755-0e143f2a19c7', '30be3c9b-166f-51fe-ba5d-c04ecbdc8ffc', 'It is multiplied by about 0.71', 'C', true, 2),
('7a0f5c7f-0c14-5bab-87ac-7ab99e42f62e', '30be3c9b-166f-51fe-ba5d-c04ecbdc8ffc', 'It is multiplied by about 1.4', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('52319284-99a7-50ac-b73d-e20447dc3ff1', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 9, 9, 'Which statement defines magnetic flux density B?', NULL, 1, 'multiple_choice'::answer_type, 'The force per unit current per unit length on a wire at right angles to the field', NULL, false, NULL, false, NULL, 'B = F/(IL) with the wire perpendicular to the field. Mark scheme (1 mark). B1: C (The force per unit current per unit length on a wire at right angles to the field).', 1),
('68090c12-ccb9-5590-8088-71826d6b0be7', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 10, 10, 'Which unit is equivalent to the tesla?', NULL, 1, 'multiple_choice'::answer_type, 'N A⁻¹ m⁻¹', NULL, false, NULL, false, NULL, 'B = F/(IL), so 1 T = 1 N A⁻¹ m⁻¹. Mark scheme (1 mark). B1: A (N A⁻¹ m⁻¹).', 1),
('a813ee17-8ea0-5133-a071-5f9fc1c34447', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 11, 11, 'A 0.30 m wire carrying 1.5 A at right angles to a uniform field feels a force of 0.090 N. Calculate the flux density.', NULL, 1, 'numeric'::answer_type, '0.2', 'T', false, NULL, false, NULL, 'B = F/(IL) = 0.090 ÷ (1.5 × 0.30) = 0.20 T. Mark scheme (2 marks). C1: B = F/(IL). A1: B = 0.20 T.', 2),
('75c7413d-0925-58e4-9cd1-fa95c118a001', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 12, 12, 'A square loop of side 0.25 m sits face-on to a uniform field of 0.12 T. Calculate the magnetic flux through the loop.', NULL, 1, 'numeric'::answer_type, '0.0075', 'Wb', false, NULL, false, NULL, 'Φ = BA = 0.12 × 0.25² = 7.5 × 10⁻³ Wb. Mark scheme (2 marks). C1: Φ = BA. A1: Φ = 0.0075 Wb.', 2),
('ed90da4a-fa6a-5450-a18f-0fae05fce0ce', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 13, 13, 'Which unit is equivalent to the weber?', NULL, 1, 'multiple_choice'::answer_type, 'T m²', NULL, false, NULL, false, NULL, 'Φ = BA, so 1 Wb = 1 T m². Mark scheme (1 mark). B1: D (T m²).', 1),
('b5bc4198-533a-5b1b-bd77-ae734b399162', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 14, 14, 'The Earth''s field of 50 µT passes at right angles through a window of area 2.0 m². Calculate the flux through the window.', NULL, 1, 'numeric'::answer_type, '1e-4', 'Wb', false, NULL, false, NULL, 'Φ = BA = 50 × 10⁻⁶ × 2.0 = 1.0 × 10⁻⁴ Wb. Mark scheme (2 marks). C1: Φ = BA with B in T. A1: Φ = 1.0 × 10⁻⁴ Wb.', 2),
('518d14ae-3743-57c5-8882-09744ad4980f', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 15, 15, 'How is a uniform magnetic field represented on a diagram?', NULL, 1, 'multiple_choice'::answer_type, 'By parallel, equally spaced field lines', NULL, false, NULL, false, NULL, 'Equal spacing shows equal strength; parallel lines show the same direction everywhere. Mark scheme (1 mark). B1: B (By parallel, equally spaced field lines).', 1),
('8afc6978-aefe-5088-9a34-696765db2aeb', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 16, 16, 'Each turn of a 300-turn pickup coil has a flux of 2.0 × 10⁻⁴ Wb through it. What is the total flux linkage?', NULL, 1, 'numeric'::answer_type, '0.06', 'Wb', false, NULL, false, NULL, 'NΦ = 300 × 2.0 × 10⁻⁴ = 0.060 Wb. Mark scheme (2 marks). C1: flux linkage = NΦ. A1: NΦ = 0.060 Wb.', 2),
('b15db304-35b8-563c-952e-cd59e79b98c5', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 17, 17, 'In which orientation is the flux through a flat coil in a uniform field greatest?', NULL, 1, 'multiple_choice'::answer_type, 'When the plane of the coil is at right angles to the field', NULL, false, NULL, false, NULL, 'Φ = BA cos θ, where θ is the angle between the field and the normal to the coil. Mark scheme (1 mark). B1: C (When the plane of the coil is at right angles to the field).', 1),
('ed4ef6a8-d78e-5109-9b38-eb80a785ea7c', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 18, 18, 'A field of 0.30 T makes an angle of 30° with the normal to a coil of area 0.010 m². Calculate the flux through the coil.', NULL, 1, 'numeric'::answer_type, '0.002598', 'Wb', false, NULL, false, NULL, 'Φ = BA cos θ = 0.30 × 0.010 × cos 30° = 0.00260 Wb. Mark scheme (2 marks). C1: Φ = BA cos θ. A1: Φ = 0.00260 Wb.', 2),
('88f12a7c-8e3b-5bb9-8e3b-0ced959fe955', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 19, 19, 'Which statement about magnetic flux density and magnetic flux is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Flux density is a vector; flux is a scalar', NULL, false, NULL, false, NULL, 'B has a direction; Φ = BA cos θ is a single number for a given surface. Mark scheme (1 mark). B1: A (Flux density is a vector; flux is a scalar).', 1),
('a8f690d5-af52-5376-8139-e4f777601d4e', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 20, 20, 'A Hall-probe check finds that a flux of 4.5 × 10⁻⁴ Wb passes face-on through a 3.0 × 10⁻³ m² loop. Find the flux density.', NULL, 1, 'numeric'::answer_type, '0.15', 'T', false, NULL, false, NULL, 'B = Φ/A = 4.5 × 10⁻⁴ ÷ 3.0 × 10⁻³ = 0.15 T. Mark scheme (2 marks). C1: B = Φ/A. A1: B = 0.15 T.', 2),
('0ada3cab-5a36-5b4d-acb1-4a32217f6f39', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 21, 21, 'At most places on the Earth''s surface, how is the Earth''s magnetic field directed?', NULL, 1, 'multiple_choice'::answer_type, 'At an angle to the horizontal, so it has both horizontal and vertical components', NULL, false, NULL, false, NULL, 'The angle below the horizontal is called the angle of dip. Mark scheme (1 mark). B1: D (At an angle to the horizontal, so it has both horizontal and vertical components).', 1),
('c2776539-a0ab-5760-9f3a-9020118d5d58', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 22, 22, 'A 1.0 m length of wire carries 1.0 A at right angles to a field of 0.35 T. Calculate the force on it.', NULL, 1, 'numeric'::answer_type, '0.35', 'N', false, NULL, false, NULL, 'F = BIL = 0.35 × 1.0 × 1.0 = 0.35 N: numerically equal to B, as the definition of the tesla shows. Mark scheme (2 marks). C1: F = BIL. A1: F = 0.35 N.', 2),
('346f4ca4-33d9-5396-a7a1-7ab6ab304b22', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 23, 23, 'What does the field between flat north and south poles facing each other look like?', NULL, 1, 'multiple_choice'::answer_type, 'Nearly uniform, with parallel lines from the north pole to the south pole', NULL, false, NULL, false, NULL, 'Between close, flat, opposite poles the field is approximately uniform. Mark scheme (1 mark). B1: B (Nearly uniform, with parallel lines from the north pole to the south pole).', 1),
('e16fd23b-786e-571f-81ca-624de8752220', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 24, 24, 'A 10-turn coil of area 0.010 m² lies face-on to a field of 0.020 T. Calculate the flux linkage.', NULL, 1, 'numeric'::answer_type, '0.002', 'Wb', false, NULL, false, NULL, 'NΦ = NBA = 10 × 0.020 × 0.010 = 2.0 × 10⁻³ Wb. Mark scheme (1 mark). A1: NΦ = 0.0020 Wb.', 1),
('cde1d80c-fd4a-5cf1-92a9-aa3fcd0d1cc6', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 25, 25, 'At a location, the Earth''s field is 50 µT and the angle of dip is 66°. Calculate the horizontal component of the field, in µT.', NULL, 2, 'numeric'::answer_type, '20.34 uT', 'µT', false, NULL, false, NULL, 'B_h = B cos 66° = 50 × cos 66° = 20.3 µT. Mark scheme (3 marks). C1: resolve with dip angle. C1: cosine for horizontal. A1: B_h = 20.3 µT.', 3),
('edacce36-7d65-532c-9fbe-719bbc1db30d', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 26, 26, 'The vertical component of the Earth''s field is 45 µT. Calculate the flux through a horizontal roof of area 4.0 m².', NULL, 2, 'numeric'::answer_type, '1.8e-4', 'Wb', false, NULL, false, NULL, 'Only the vertical component passes through a horizontal surface: Φ = 45 × 10⁻⁶ × 4.0 = 1.8 × 10⁻⁴ Wb. Mark scheme (3 marks). C1: vertical component. C1: Φ = BA. A1: Φ = 1.8 × 10⁻⁴ Wb.', 3),
('01ac5927-2012-5d5c-861b-3b9a9b8b15f1', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 27, 27, 'A 100-turn coil of area 0.0050 m² starts face-on to a 0.20 T field and is turned until its normal is at 60° to the field. Calculate the change in flux linkage.', NULL, 2, 'numeric'::answer_type, '0.05', 'Wb', false, NULL, false, NULL, 'Δ(NΦ) = NBA(1 − cos 60°) = 100 × 0.20 × 0.0050 × (1 − 0.50) = 0.050 Wb. Mark scheme (4 marks). C1: NΦ = NBA cos θ. C1: initial and final values. C1: difference. A1: Δ(NΦ) = 0.050 Wb.', 4),
('f9b99a95-d1bd-5f53-834d-4fd2e1ea5eac', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 28, 28, 'The area of a coil is doubled and the flux density is halved, with the coil face-on to the field each time. What happens to the flux through the coil?', NULL, 2, 'multiple_choice'::answer_type, 'It stays the same', NULL, false, NULL, false, NULL, 'Φ = BA, and doubling A while halving B leaves the product unchanged. Mark scheme (3 marks). C1: Φ = BA. C1: product unchanged. A1: C (It stays the same).', 3),
('e3e59078-3eda-5126-875d-0f7ad73487e8', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 29, 29, 'A circular coil of radius 3.0 cm lies face-on to a field of 0.40 T. Calculate the flux through it.', NULL, 2, 'numeric'::answer_type, '0.001131', 'Wb', false, NULL, false, NULL, 'A = π × 0.030² = 0.00283 m². Φ = 0.40 × 0.002827 = 0.00113 Wb. Mark scheme (3 marks). C1: A = πr². C1: Φ = BA. A1: Φ = 0.00113 Wb.', 3),
('211ecb27-5f2e-50f1-acc6-3584fd9d8312', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 30, 30, 'What area must a coil have, face-on to a 0.25 T field, for the flux through it to be 2.0 × 10⁻³ Wb?', NULL, 2, 'numeric'::answer_type, '0.008', 'm²', false, NULL, false, NULL, 'A = Φ/B = 2.0 × 10⁻³ ÷ 0.25 = 8.0 × 10⁻³ m². Mark scheme (3 marks). C1: A = Φ/B. C1: substitution. A1: A = 0.0080 m².', 3),
('58948a2c-4f79-5740-a089-a10702c1e3d8', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 31, 31, 'A coil of area A is in a uniform field B, and the normal to the coil makes angle θ with the field. Which expression gives the flux through it?', NULL, 2, 'multiple_choice'::answer_type, 'BA cos θ', NULL, false, NULL, false, NULL, 'Only the component of B along the normal, B cos θ, passes through the coil. Mark scheme (3 marks). C1: component along normal. C1: cos θ. A1: A (BA cos θ).', 3),
('fd1261cc-21f1-5d84-8d29-a2ec6416bcc3', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 32, 32, 'At what angle between the field and the normal to a coil is the flux through the coil half its maximum value?', NULL, 2, 'numeric'::answer_type, '60', '°', false, NULL, false, NULL, 'Φ/Φ_max = cos θ = 0.50, so θ = cos⁻¹ 0.50 = 60°. Mark scheme (4 marks). M1: Φ = Φ_max cos θ. C1: cos θ = 0.50. C1: angle. A1: θ = 60°.', 4),
('62305be7-f217-570b-b1ee-89efd7375dcc', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 33, 33, 'The field inside a solenoid of radius 2.0 cm is 0.010 T. Calculate the flux through its cross-section.', NULL, 2, 'numeric'::answer_type, '1.257e-5', 'Wb', false, NULL, false, NULL, 'Φ = BA = 0.010 × π × 0.020² = 1.26 × 10⁻⁵ Wb. Mark scheme (3 marks). C1: A = πr². C1: Φ = BA. A1: Φ = 1.26 × 10⁻⁵ Wb.', 3),
('0733363b-209c-527c-ac7f-cc7e7af79897', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 34, 34, 'Which statement defines the weber?', NULL, 2, 'multiple_choice'::answer_type, 'The flux through 1 m² when a field of 1 T passes at right angles through it', NULL, false, NULL, false, NULL, 'From Φ = BA with the field perpendicular to the surface: 1 Wb = 1 T × 1 m². Mark scheme (3 marks). C1: Φ = BA. C1: perpendicular. A1: D (The flux through 1 m² when a field of 1 T passes at right angles through it).', 3),
('1d0f6b38-1543-5f08-a1cf-da03f9c20251', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 35, 35, 'A 25 cm length of wire at right angles to a uniform field carries 4.0 A and feels a force of 0.15 N. Calculate the flux density, in mT.', NULL, 2, 'numeric'::answer_type, '150 mT', 'mT', false, NULL, false, NULL, 'B = F/(IL) = 0.15 ÷ (4.0 × 0.25) = 0.15 T. In mT: 0.15 × 1000 = 150. Mark scheme (3 marks). C1: B = F/(IL). C1: conversion. A1: B = 150 mT.', 3),
('0935141e-d8ff-5145-a560-a09c6a1d0b60', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 36, 36, 'A 500-turn coil of area 0.010 m² is held horizontally where the vertical component of the Earth''s field is 4.4 × 10⁻⁵ T. Calculate the flux linkage.', NULL, 2, 'numeric'::answer_type, '2.2e-4', 'Wb', false, NULL, false, NULL, 'NΦ = NB_vA = 500 × 4.4 × 10⁻⁵ × 0.010 = 2.2 × 10⁻⁴ Wb. Mark scheme (4 marks). B1: vertical component through horizontal coil. C1: NΦ = NBA. C1: substitution. A1: NΦ = 2.2 × 10⁻⁴ Wb.', 4),
('74ac72d3-8f05-5efc-92ff-61b2e9a8b4c9', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 37, 37, 'Why can two magnetic field lines never cross?', NULL, 2, 'multiple_choice'::answer_type, 'The field has only one direction at each point, and the line''s direction shows it', NULL, false, NULL, false, NULL, 'If lines crossed, a compass at the crossing would have to point two ways at once. Mark scheme (3 marks). C1: unique direction at a point. C1: line shows that direction. A1: B (The field has only one direction at each point, and the line''s direction shows it).', 3),
('12702c10-59e6-57e6-a6ac-b41b364beb9d', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 38, 38, 'Calculate (flux through a coil whose normal is at 30° to the field) ÷ (flux when the coil is face-on).', NULL, 2, 'numeric'::answer_type, '0.866', NULL, false, NULL, false, NULL, 'Ratio = cos 30° = 0.866. Mark scheme (3 marks). C1: Φ ∝ cos θ. C1: value. A1: ratio = 0.866.', 3),
('a293d3a5-f190-5232-996c-e8e4cb3c1253', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 39, 39, 'For a flat surface of area A at right angles to a uniform field, which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'B = Φ/A, so flux density is flux per unit area', NULL, false, NULL, false, NULL, 'This is why the tesla is also the weber per square metre. Mark scheme (4 marks). C1: Φ = BA. C1: B = Φ/A. C1: T = Wb m⁻². A1: C (B = Φ/A, so flux density is flux per unit area).', 4),
('004da130-b38a-5c58-9d83-7eab7503840d', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 40, 40, 'A flux of 3.0 × 10⁻³ Wb passes through a loop of area 0.020 m² whose normal is at 40° to the field. Calculate the flux density.', NULL, 2, 'numeric'::answer_type, '0.1958', 'T', false, NULL, false, NULL, 'B = Φ/(A cos θ) = 3.0 × 10⁻³ ÷ (0.020 × cos 40°) = 0.196 T. Mark scheme (3 marks). C1: Φ = BA cos θ. C1: rearranged. A1: B = 0.196 T.', 3),
('ca8aa8d4-daa6-5d31-bbf4-5e2605a85739', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 41, 41, 'A rectangular coil of 200 turns measuring 4.0 cm × 5.0 cm is in a uniform field of 0.15 T. (a) Calculate the maximum flux linkage. (b) Calculate the flux linkage when the coil has been turned 30° from that position. (c) Calculate the change in flux linkage as the coil turns from the maximum position until its plane is parallel to the field. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.05196', 'Wb', false, NULL, false, NULL, '(a) NBA = 200 × 0.15 × 0.040 × 0.050 = 0.060 Wb. (b) NΦ = 0.060 × cos 30° = 0.0520 Wb. (c) The plane is then parallel, so NΦ = 0 and the change is 0.060 Wb. Mark scheme (6 marks). C1: area in m². C1: NBA. M1: × cos θ. C1: value. B1: change equals maximum. A1: NΦ = 0.0520 Wb.', 6),
('defecf6d-76c4-5765-8e40-92fe75657b0e', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 42, 42, 'At a certain place the Earth''s horizontal field component is 1.9 × 10⁻⁵ T and the angle of dip is 68°. (a) Calculate the total flux density. (b) Calculate the vertical component. (c) Calculate the flux through a horizontal roof 1.5 m × 2.0 m. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.411e-4', 'Wb', false, NULL, false, NULL, '(a) B = 1.9 × 10⁻⁵ ÷ cos 68° = 5.07 × 10⁻⁵ T. (b) B_v = 5.072 × 10⁻⁵ × sin 68° = 4.70 × 10⁻⁵ T. (c) Φ = 4.703 × 10⁻⁵ × 1.5 × 2.0 = 1.41 × 10⁻⁴ Wb. Mark scheme (5 marks). C1: B = B_h/cos dip. C1: B_v = B sin dip. M1: vertical component through roof. C1: Φ = B_vA. A1: Φ = 1.41 × 10⁻⁴ Wb.', 5),
('f60b3040-d939-537a-97cb-89e93c26266c', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 43, 43, 'A Hall probe is moved along the axis of a bar magnet: d/cm = 2.0, 4.0, 6.0, 8.0 and B/mT = 40, 5.0, 1.48, 0.625. (a) Show that B is not inversely proportional to d. (b) Show that Bd³ is constant. (c) Use your result to predict B at d = 10 cm, in mT. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.32 mT', 'mT', false, NULL, false, NULL, '(a) Bd = 80 at 2.0 cm but 5.0 at 8.0 cm, so B is not ∝ 1/d. (b) Bd³ = 40 × 2.0³ = 320 and 0.625 × 8.0³ = 320 (also 5.0 × 4.0³ = 320), so Bd³ is constant. (c) B = 320 ÷ 10³ = 0.32 mT. Mark scheme (6 marks). B1: Bd not constant. C1: Bd³ values. B1: constant. M1: B = k/d³. C1: prediction. A1: B = 0.32 mT.', 6),
('2fbff5e6-8e73-5560-ae73-921ba0bfb6d1', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 44, 44, 'A solenoid with no core gives a field of 2.0 mT. An iron core is inserted, increasing the field by a factor of 500. The core has a cross-sectional area of 2.0 × 10⁻⁴ m², and a 50-turn coil is wound round it. (a) Calculate the new flux density. (b) Calculate the flux in the core. (c) Calculate the flux linkage of the 50-turn coil. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.01', 'Wb', false, NULL, false, NULL, '(a) B = 500 × 2.0 × 10⁻³ = 1.0 T. (b) Φ = 1.0 × 2.0 × 10⁻⁴ = 2.0 × 10⁻⁴ Wb. (c) NΦ = 50 × 2.0 × 10⁻⁴ = 0.010 Wb. Mark scheme (5 marks). C1: new B. C1: Φ = BA. M1: same flux through the coil. C1: NΦ. A1: NΦ = 0.010 Wb.', 5),
('eea728f6-37ff-5704-8059-8a8a459a4882', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 45, 45, 'A wire 0.050 m long carrying 2.0 A is placed at different angles θ to a uniform field: θ = 30°, 60°, 90° and F/mN = 12, 21, 24. (a) Show that the readings are consistent with F ∝ sin θ. (b) Calculate the flux density. (c) Predict the force at θ = 45°, in mN. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.24', 'T', false, NULL, false, NULL, '(a) F/sin θ = 12 ÷ sin 30° = 24, 21 ÷ sin 60° = 24.2 and 24 ÷ sin 90° = 24 mN: constant within error. (b) At 90°: B = F/(IL) = 24 × 10⁻³ ÷ (2.0 × 0.050) = 0.24 T. (c) F = 24 × sin 45° = 17.0 mN. Mark scheme (6 marks). C1: F/sin θ values. B1: constant. C1: B = F/(IL) at 90°. C1: substitution. C1: prediction. A1: B = 0.24 T.', 6),
('448ed331-4dce-59ef-99c3-1b4f431bcb0a', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 46, 46, 'Coil A has 100 turns of radius 2.0 cm; coil B has 25 turns of radius 4.0 cm. Both are face-on to the same uniform field. (a) Write the flux linkage of each in terms of B. (b) Calculate (flux linkage of A) ÷ (flux linkage of B). (c) Explain the result. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1', NULL, false, NULL, false, NULL, '(a) NΦ_A = 100 × B × π × 0.020²; NΦ_B = 25 × B × π × 0.040². (b) Ratio = (100 × 0.020²) ÷ (25 × 0.040²) = 1.0. (c) B has four times the area per turn but a quarter of the turns. Mark scheme (5 marks). C1: NΦ = NBπr². C1: both expressions. C1: ratio. B1: area × turns equal. A1: ratio = 1.0.', 5),
('96b859e6-370f-5483-b204-7a4652208b78', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 47, 47, 'A rectangular loop 0.10 m × 0.20 m lies flat. Half of its area is in a field of 0.20 T pointing upwards and the other half is in a field of 0.050 T pointing downwards. (a) Calculate the flux through each half. (b) Calculate the net flux through the loop. (c) Explain why the fluxes are combined with opposite signs. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.0015', 'Wb', false, NULL, false, NULL, '(a) Each half has area 0.010 m²: Φ₁ = 0.20 × 0.010 = 2.0 × 10⁻³ Wb up; Φ₂ = 0.050 × 0.010 = 5.0 × 10⁻⁴ Wb down. (b) Net Φ = 2.0 × 10⁻³ − 5.0 × 10⁻⁴ = 1.5 × 10⁻³ Wb. (c) Flux is counted relative to a chosen normal; field passing the opposite way counts as negative. Mark scheme (5 marks). C1: area of each half. C1: each flux. M1: subtract opposite fluxes. B1: sign convention. A1: Φ = 0.0015 Wb.', 5),
('24d98241-2e61-58ed-8eb5-397617a795e1', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 48, 48, 'A 50-turn rectangular coil 0.30 m × 0.20 m lies flat on a table where the vertical component of the Earth''s field is 44 µT. The coil is flipped over. (a) Calculate the initial flux linkage. (b) Explain why the flux linkage changes sign when the coil is flipped. (c) Calculate the magnitude of the change in flux linkage. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.64e-4', 'Wb', false, NULL, false, NULL, '(a) NΦ = 50 × 44 × 10⁻⁶ × 0.30 × 0.20 = 1.32 × 10⁻⁴ Wb. (b) The field now enters the opposite face of the coil, relative to its normal. (c) Change = 2 × 1.320 × 10⁻⁴ = 2.64 × 10⁻⁴ Wb. Mark scheme (5 marks). C1: NBA. B1: reversal relative to normal. M1: change = 2NBA. C1: value. A1: Δ(NΦ) = 2.64 × 10⁻⁴ Wb.', 5),
('511c9422-b4ff-5678-9119-59ffcc6c5b61', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 49, 49, '(a) Show that 1 T = 1 N A⁻¹ m⁻¹ and hence that 1 Wb = 1 N m A⁻¹. (b) A field of 0.40 T passes at right angles through an area of 25 cm². Calculate the flux. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.001', 'Wb', false, NULL, false, NULL, '(a) B = F/(IL) gives T = N A⁻¹ m⁻¹; Φ = BA gives Wb = N A⁻¹ m⁻¹ × m² = N m A⁻¹. (b) 25 cm² = 25 × 10⁻⁴ m², so Φ = 0.40 × 25 × 10⁻⁴ = 1.0 × 10⁻³ Wb. Mark scheme (5 marks). B1: tesla from F = BIL. B1: weber from Φ = BA. C1: cm² to m². C1: Φ = BA. A1: Φ = 0.0010 Wb.', 5),
('57367623-98e0-5d4b-a7ac-d61274be8022', '451c0a56-584e-41c1-958b-7b940530308c', 'ec5a5988-7f11-54f1-aea3-84eee8a77be3', 'a-level', '24.3', '9702 coursebook 24.3 · Magnetic fields and flux density', 50, 50, 'A small 30-turn coil of area 1.5 cm² is placed inside a solenoid where the field is 8.0 mT, with the normal to the coil at 25° to the solenoid''s axis. (a) Calculate the flux through one turn. (b) Calculate the flux linkage. (c) State the orientation that would make the flux linkage zero. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3.263e-5', 'Wb', false, NULL, false, NULL, '(a) Φ = 8.0 × 10⁻³ × 1.5 × 10⁻⁴ × cos 25° = 1.09 × 10⁻⁶ Wb. (b) NΦ = 30 × 1.088 × 10⁻⁶ = 3.26 × 10⁻⁵ Wb. (c) With the plane of the coil parallel to the axis (normal at 90°). Mark scheme (5 marks). C1: area in m². C1: Φ = BA cos θ. C1: NΦ. B1: plane parallel to field. A1: NΦ = 3.26 × 10⁻⁵ Wb.', 5)
