('9fec7a14-2a28-56db-9aee-c7023f8da5dd', 'b15db304-35b8-563c-952e-cd59e79b98c5', 'When the coil is at 45° to the field', 'B', false, 1),
('31d66d89-54a1-56e0-8b1a-74d05b9d5431', 'b15db304-35b8-563c-952e-cd59e79b98c5', 'When the plane of the coil is at right angles to the field', 'C', true, 2),
('228cb405-532e-5ac9-9d3a-ef0bd91a651a', 'b15db304-35b8-563c-952e-cd59e79b98c5', 'The flux is the same in all orientations', 'D', false, 3),
('6569b59d-03d1-57fc-be17-a0d8488555fd', '88f12a7c-8e3b-5bb9-8e3b-0ced959fe955', 'Flux density is a vector; flux is a scalar', 'A', true, 0),
