('b7e16ed3-4e49-5fc2-b072-80f7b7d07985', '88f12a7c-8e3b-5bb9-8e3b-0ced959fe955', 'Flux is a vector; flux density is a scalar', 'D', false, 3),
('0bee0f37-0920-53a7-9fd1-554d4bac2bf5', '0ada3cab-5a36-5b4d-acb1-4a32217f6f39', 'Exactly horizontal', 'A', false, 0),
('6a64d21e-6ce3-534c-8937-2b89c8bcb9e1', '0ada3cab-5a36-5b4d-acb1-4a32217f6f39', 'Exactly vertical', 'B', false, 1),
('0af005e6-f330-509d-a9af-a71026de4130', '0ada3cab-5a36-5b4d-acb1-4a32217f6f39', 'From south to north along the ground only', 'C', false, 2),
('d214a96b-b46c-59fd-a17e-49ba9cb25a35', '0ada3cab-5a36-5b4d-acb1-4a32217f6f39', 'At an angle to the horizontal, so it has both horizontal and vertical components', 'D', true, 3),
('a8dbc2b0-e424-5806-b364-e5f4e3916a2f', '346f4ca4-33d9-5396-a7a1-7ab6ab304b22', 'Concentric circles around the poles', 'A', false, 0),
('3b997722-1a72-5f2b-b2f1-a9f1f9b7b3ce', '346f4ca4-33d9-5396-a7a1-7ab6ab304b22', 'Nearly uniform, with parallel lines from the north pole to the south pole', 'B', true, 1),
('d252a85f-72ec-53f0-a712-f3ab834487b7', '346f4ca4-33d9-5396-a7a1-7ab6ab304b22', 'Lines curving back into the north pole', 'C', false, 2),
('950a5cdc-83a6-59a7-b5f6-c7c9ca4dd9ef', '346f4ca4-33d9-5396-a7a1-7ab6ab304b22', 'No field, because the poles cancel', 'D', false, 3),
('462e742d-330e-5f0c-b021-29524df716e9', 'f9b99a95-d1bd-5f53-834d-4fd2e1ea5eac', 'It doubles', 'A', false, 0),
('bd84aef8-7f6e-5051-9513-53910bb716a4', 'f9b99a95-d1bd-5f53-834d-4fd2e1ea5eac', 'It halves', 'B', false, 1),
('4b20128c-17d7-512f-9f6c-67794d64017e', 'f9b99a95-d1bd-5f53-834d-4fd2e1ea5eac', 'It stays the same', 'C', true, 2),
('40411932-1990-5225-b8f3-6e66a2124c95', 'f9b99a95-d1bd-5f53-834d-4fd2e1ea5eac', 'It quadruples', 'D', false, 3),
('6eda8428-c402-5d90-9b78-0928fd55d4a6', '58948a2c-4f79-5740-a089-a10702c1e3d8', 'BA cos θ', 'A', true, 0),
('2a7700d0-4a2e-5573-a11f-edb5faf51489', '58948a2c-4f79-5740-a089-a10702c1e3d8', 'BA sin θ', 'B', false, 1),
('5023e984-e455-5631-b9d3-9cbe8e3a32cc', '58948a2c-4f79-5740-a089-a10702c1e3d8', 'BA/cos θ', 'C', false, 2),
('6cd64824-6d0a-5a31-aa8a-43cdce1e01a9', '58948a2c-4f79-5740-a089-a10702c1e3d8', 'BA tan θ', 'D', false, 3),
('b56b599e-fbd7-5e7f-b07c-0cf7942b1728', '0733363b-209c-527c-ac7f-cc7e7af79897', 'The flux density that gives 1 N on 1 m of wire carrying 1 A', 'A', false, 0),
('6608513e-6012-5b90-aabc-0b7bcbe2690c', '0733363b-209c-527c-ac7f-cc7e7af79897', 'The field produced by 1 A at 1 m', 'B', false, 1),
('d2fa8024-f494-517a-8597-1b9f51fd49d9', '0733363b-209c-527c-ac7f-cc7e7af79897', 'The flux through a coil of 1 turn in any field', 'C', false, 2),
('d70290d9-474a-5523-ba9a-c92c65e290e3', '0733363b-209c-527c-ac7f-cc7e7af79897', 'The flux through 1 m² when a field of 1 T passes at right angles through it', 'D', true, 3),
('e274af2d-7609-56f0-b188-011e2737cdaf', '74ac72d3-8f05-5efc-92ff-61b2e9a8b4c9', 'Field lines repel each other', 'A', false, 0),
('100f1264-435f-507e-86ef-f2685a99c444', '74ac72d3-8f05-5efc-92ff-61b2e9a8b4c9', 'The field has only one direction at each point, and the line''s direction shows it', 'B', true, 1),
('80cbb6ed-33b8-599b-b992-5fdf5514b5b0', '74ac72d3-8f05-5efc-92ff-61b2e9a8b4c9', 'Crossing would make the field zero', 'C', false, 2),
('84977f44-2e92-5ea1-aa67-f7912ea71934', '74ac72d3-8f05-5efc-92ff-61b2e9a8b4c9', 'Field lines are made of magnetic material', 'D', false, 3),
('6c310b02-3503-56c6-93a9-a0bccbd83446', 'a293d3a5-f190-5232-996c-e8e4cb3c1253', 'Φ = B/A', 'A', false, 0),
('b5e4e72c-e78d-5cbb-9534-355bbc53089e', 'a293d3a5-f190-5232-996c-e8e4cb3c1253', 'B = ΦA', 'B', false, 1),
('ea83c34c-34df-50ff-8191-b11124659c97', 'a293d3a5-f190-5232-996c-e8e4cb3c1253', 'B = Φ/A, so flux density is flux per unit area', 'C', true, 2),
('85e3208b-a9a5-5e77-89b8-34ab6ec33319', 'a293d3a5-f190-5232-996c-e8e4cb3c1253', 'Φ and B have the same unit', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('4173550b-61a9-5ca4-ae3f-7d5e0f25a579', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 7, 7, 'What does the output voltage of a Hall probe depend on?', NULL, 1, 'multiple_choice'::answer_type, 'The component of the magnetic flux density at right angles to the probe''s flat face', NULL, false, NULL, false, NULL, 'The Hall voltage is proportional to the perpendicular component of B. Mark scheme (1 mark). B1: C (The component of the magnetic flux density at right angles to the probe''s flat face).', 1),
('8a0e3978-d914-5159-8222-fea9075cf0c3', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 8, 8, 'When a current flows through a wire between the poles of a magnet resting on a top-pan balance, the reading changes by 1.5 g. Calculate the size of the force on the wire. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '0.01472', 'N', false, NULL, false, NULL, 'F = Δm × g = 1.5 × 10⁻³ × 9.81 = 0.0147 N. Mark scheme (2 marks). C1: convert grams to kg and × g. A1: F = 0.0147 N.', 2),
('211d7679-2c05-59bb-8e7b-f014728bf1a7', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 9, 9, 'A 0.040 m length of wire at right angles to a field carries 2.5 A and feels a force of 0.020 N. Calculate the flux density.', NULL, 1, 'numeric'::answer_type, '0.2', 'T', false, NULL, false, NULL, 'B = F/(IL) = 0.020 ÷ (2.5 × 0.040) = 0.20 T. Mark scheme (2 marks). C1: B = F/(IL). A1: B = 0.20 T.', 2),
('de1df757-0de6-5c9d-a9ce-2cf2ece1c617', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 10, 10, 'A magnet sits on a top-pan balance with a fixed wire passing between its poles. When a current flows, the reading increases. Why?', NULL, 1, 'multiple_choice'::answer_type, 'The magnet pushes up on the wire, so by Newton''s third law the wire pushes down on the magnet', NULL, false, NULL, false, NULL, 'The forces on wire and magnet are equal and opposite. Mark scheme (1 mark). B1: A (The magnet pushes up on the wire, so by Newton''s third law the wire pushes down on the magnet).', 1),
('9a7a510d-1ee0-5961-9e46-1b288d0c3047', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 11, 11, 'How should a Hall probe be held to give its maximum reading?', NULL, 1, 'multiple_choice'::answer_type, 'With its flat face at right angles to the field lines', NULL, false, NULL, false, NULL, 'Only the perpendicular component of B produces the Hall voltage. Mark scheme (1 mark). B1: D (With its flat face at right angles to the field lines).', 1),
('a94b1bb0-de6a-518a-9c15-18e368b792f6', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 12, 12, 'A calibrated Hall probe gives 1.0 mV for every 1.0 mT. Its reading near a magnet is 35 mV. What is the flux density, in mT?', NULL, 1, 'numeric'::answer_type, '35 mT', 'mT', false, NULL, false, NULL, 'B = 35 ÷ 1.0 = 35 mT. Mark scheme (2 marks). C1: reading ÷ sensitivity. A1: B = 35 mT.', 2),
('a112e956-10b0-5379-bad1-2c28356d705a', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 13, 13, 'In a top-pan balance experiment, why are readings also taken with the current reversed?', NULL, 1, 'multiple_choice'::answer_type, 'To check that the change reverses, so that effects not due to the magnetic force can be averaged out', NULL, false, NULL, false, NULL, 'Reversing the current reverses only the magnetic force, so averaging the two changes removes zero errors. Mark scheme (1 mark). B1: B (To check that the change reverses, so that effects not due to the magnetic force can be averaged out).', 1),
('5fc986c6-57af-58f6-9590-8f75f8fc5a35', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 14, 14, 'A wire carrying 3.0 A crosses a 5.0 cm wide magnetic field at right angles. The balance reading changes by 0.92 g. Calculate the flux density. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '0.06017', 'T', false, NULL, false, NULL, 'F = 0.92 × 10⁻³ × 9.81 = 0.00903 N. B = F/(IL) = 0.009025 ÷ (3.0 × 0.050) = 0.0602 T. Mark scheme (2 marks). C1: F = Δm g, then B = F/(IL). A1: B = 0.0602 T.', 2),
('1842a526-2e59-544d-aac0-784142ecb9b5', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 15, 15, 'Compared with a current balance, what is an advantage of a Hall probe?', NULL, 1, 'multiple_choice'::answer_type, 'It measures the field at a point, so it can map how the field varies', NULL, false, NULL, false, NULL, 'The probe''s sensor is tiny, so it samples a small region. Mark scheme (1 mark). B1: C (It measures the field at a point, so it can map how the field varies).', 1),
('d2051ff5-4a62-5aab-90f8-9e993a24686f', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 16, 16, 'A 0.060 m length of wire carrying 4.0 A lies at right angles to a field of 50 mT. Calculate the force on it.', NULL, 1, 'numeric'::answer_type, '0.012', 'N', false, NULL, false, NULL, 'F = BIL = 50 × 10⁻³ × 4.0 × 0.060 = 0.012 N. Mark scheme (2 marks). C1: F = BIL. A1: F = 0.012 N.', 2),
('49bf27f3-0bc3-5f8e-9bf6-1d7ecc545835', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 17, 17, 'A Hall probe is turned so that its face is at an angle to the field. How does its reading change?', NULL, 1, 'multiple_choice'::answer_type, 'It decreases, because only the perpendicular component of B is measured', NULL, false, NULL, false, NULL, 'The reading is proportional to B cos θ, where θ is between B and the normal to the face. Mark scheme (1 mark). B1: A (It decreases, because only the perpendicular component of B is measured).', 1),
('9f5ecd37-5736-5269-8754-a4cdad131789', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 18, 18, 'A balance reading changes from 152.40 g to 151.88 g when a current is switched on. Calculate the size of the magnetic force, in mN. Take g = 9.81 m s⁻².', NULL, 1, 'numeric'::answer_type, '5.101 mN', 'mN', false, NULL, false, NULL, 'Δm = 152.40 − 151.88 = 0.52 g. F = 0.52 × 10⁻³ × 9.81 = 0.00510 N. In mN: 0.005101 × 1000 = 5.10. Mark scheme (2 marks). C1: F = Δm g. A1: F = 5.10 mN.', 2),
('b6676c2f-aafb-5f4e-b928-0091266c217c', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 19, 19, 'Which three quantities must be measured to find B with a current balance?', NULL, 1, 'multiple_choice'::answer_type, 'The force on the wire, the current, and the length of wire in the field', NULL, false, NULL, false, NULL, 'B = F/(IL), so F, I and L are all needed, with the wire at right angles to the field. Mark scheme (1 mark). B1: D (The force on the wire, the current, and the length of wire in the field).', 1),
('5b08e033-9ed6-58d7-a1bd-4c8706951b44', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 20, 20, 'A Hall probe gives an output of 0.24 V in a known field of 0.40 T. What output, in V, would it give in a field of 0.15 T?', NULL, 1, 'numeric'::answer_type, '0.09', 'V', false, NULL, false, NULL, 'Output ∝ B: 0.24 × 0.15 ÷ 0.40 = 0.090 V. Mark scheme (2 marks). C1: output proportional to B. A1: V = 0.090 V.', 2),
('b2c392b0-fc24-584a-8ad2-58199a637eae', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 21, 21, 'Why is the reading with no current flowing recorded before a top-pan balance experiment?', NULL, 1, 'multiple_choice'::answer_type, 'It is the zero reading: only the change from it is due to the magnetic force', NULL, false, NULL, false, NULL, 'The force is found from the change in reading. Mark scheme (1 mark). B1: B (It is the zero reading: only the change from it is due to the magnetic force).', 1),
('a266a3c9-1bd2-5c24-8a7b-e704faaa5cd1', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 22, 22, 'In a balance experiment the magnetic force is 4.0 mN at a certain current. What is the force, in mN, when the current is doubled?', NULL, 1, 'numeric'::answer_type, '8 mN', 'mN', false, NULL, false, NULL, 'F ∝ I: 2 × 4.0 = 8.0 mN. Mark scheme (1 mark). A1: F = 8.0 mN.', 1),
('7bbd8feb-f9ca-5af6-919f-a796ff3ac31e', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 23, 23, 'A Hall probe reads 4.2 mT when the field makes an angle of 30° with the normal to its face. Calculate the actual flux density, in mT.', NULL, 1, 'numeric'::answer_type, '4.85 mT', 'mT', false, NULL, false, NULL, 'B = reading ÷ cos 30° = 4.2 ÷ cos 30° = 4.85 mT. Mark scheme (2 marks). C1: reading = B cos θ. A1: B = 4.85 mT.', 2),
('c547ac92-1be0-549a-b2e7-3b36dd00d77c', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 24, 24, 'With a current of 3.0 A, the top-pan balance reading changes by 2.4 g. The length of wire in the field is 0.050 m. Calculate the flux density. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.157', 'T', false, NULL, false, NULL, 'F = 2.4 × 10⁻³ × 9.81 = 0.0235 N. B = 0.02354 ÷ (3.0 × 0.050) = 0.157 T. Mark scheme (3 marks). C1: F = Δm g. C1: B = F/(IL). A1: B = 0.157 T.', 3),
('f1a2c231-13eb-50b3-b253-7d6a62375bc1', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 25, 25, 'In a current balance experiment, the force is measured to ±2 %, the current to ±1 % and the length of wire in the field to ±2 %. Calculate the percentage uncertainty in B.', NULL, 2, 'numeric'::answer_type, '5', '%', false, NULL, false, NULL, 'B = F/(IL): percentage uncertainties add, 2 + 1 + 2 = 5.0 %. Mark scheme (4 marks). M1: product and quotient rule. C1: percentages add. C1: value. A1: uncertainty = 5.0%.', 4),
('94670dec-7898-5469-88c2-1bccc0ef78dd', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 26, 26, 'In a top-pan balance experiment the reading increases when the current flows. When the current is reversed, what happens?', NULL, 2, 'multiple_choice'::answer_type, 'The reading decreases below the zero value by the same amount', NULL, false, NULL, false, NULL, 'Reversing the current reverses the force on the wire and so on the magnet. Mark scheme (3 marks). C1: force reverses. C1: same magnitude. A1: C (The reading decreases below the zero value by the same amount).', 3),
('13a8ccf0-d041-5a61-853e-29db1d0d00c0', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 27, 27, 'A Hall probe reads 6.3 mT inside a solenoid carrying 2.5 A. What will it read when the current is increased to 4.0 A, in mT?', NULL, 2, 'numeric'::answer_type, '10.08 mT', 'mT', false, NULL, false, NULL, 'B ∝ I: 6.3 × 4.0 ÷ 2.5 = 10.1 mT. Mark scheme (3 marks). C1: B ∝ I. C1: substitution. A1: B = 10.1 mT.', 3),
('8590c58d-b4ca-5838-ae14-ce78a4909332', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 28, 28, 'A graph of force against current for a wire at right angles to a field has a gradient of 0.012 N A⁻¹. The length of wire in the field is 0.060 m. Calculate the flux density.', NULL, 2, 'numeric'::answer_type, '0.2', 'T', false, NULL, false, NULL, 'F = BIL, so the gradient = BL and B = 0.012 ÷ 0.060 = 0.20 T. Mark scheme (3 marks). M1: gradient = BL. C1: B. A1: B = 0.20 T.', 3),
('9fb3ade6-67f4-58a8-ae77-ae345cef8002', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 29, 29, 'Why should the whole length of wire used in the force calculation lie in the uniform region between the pole pieces?', NULL, 2, 'multiple_choice'::answer_type, 'So that B is the same along the whole length L used in F = BIL', NULL, false, NULL, false, NULL, 'Near the edges the field is weaker and non-uniform, so F would not equal BIL for the full L. Mark scheme (3 marks). C1: uniform B along L. C1: edge effects. A1: A (So that B is the same along the whole length L used in F = BIL).', 3),
('514abe16-f48f-58ea-b792-b2b5163d8f2a', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 30, 30, 'A magnet assembly reads 120.00 g on a top-pan balance. With 4.0 A in a wire that crosses its field for 0.040 m, the reading becomes 121.32 g. Calculate the flux density. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '0.08093', 'T', false, NULL, false, NULL, 'Δm = 121.32 − 120.00 = 1.32 g. F = 1.32 × 10⁻³ × 9.81 = 0.0129 N. B = 0.01295 ÷ (4.0 × 0.040) = 0.0809 T. Mark scheme (4 marks). C1: change in reading. C1: F = Δm g. C1: B = F/(IL). A1: B = 0.0809 T.', 4),
('a3de4ed7-2fc5-5055-ac39-bc4e1a9dd093', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 31, 31, 'A Hall probe gives 0.85 V in a field of 0.17 T. In an unknown field it gives 0.50 V. Calculate the unknown flux density.', NULL, 2, 'numeric'::answer_type, '0.1', 'T', false, NULL, false, NULL, 'Output ∝ B: B = 0.17 × 0.50 ÷ 0.85 = 0.10 T. Mark scheme (3 marks). C1: proportionality. C1: substitution. A1: B = 0.10 T.', 3),
('517a5b81-b1d5-51b7-9a4e-ac0dcbac3367', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 32, 32, 'Why is a Hall probe better than a current balance for investigating how the field varies across the gap of a magnet?', NULL, 2, 'multiple_choice'::answer_type, 'It is small and measures B at a point, so readings can be taken at many positions', NULL, false, NULL, false, NULL, 'A current balance gives an average over the length of wire. Mark scheme (3 marks). C1: point measurement. C1: can map field. A1: D (It is small and measures B at a point, so readings can be taken at many positions).', 3),
('fdd2b053-ed20-5103-952c-bac5657596d6', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 33, 33, 'In a pivoted current balance, the magnetic force on a wire 8.0 cm from the pivot is balanced by a rider of mass 0.50 g placed 4.0 cm from the pivot. The wire carries 2.0 A and has 0.050 m in the field. Calculate the flux density, in mT. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '24.53 mT', 'mT', false, NULL, false, NULL, 'Moments: F × 0.080 = 0.50 × 10⁻³ × 9.81 × 0.040, so F = 0.00245 N. B = 0.002453 ÷ (2.0 × 0.050) = 0.0245 T. In mT: 0.02453 × 1000 = 24.5. Mark scheme (3 marks). M1: principle of moments. C1: B = F/(IL). A1: B = 24.5 mT.', 3),
('df127486-bb1f-5ece-a5ee-7f0c001c4371', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 34, 34, 'In a current balance experiment using a strong magnet, why can the Earth''s magnetic field usually be ignored?', NULL, 2, 'multiple_choice'::answer_type, 'It is about 5 × 10⁻⁵ T, thousands of times smaller than the magnet''s field', NULL, false, NULL, false, NULL, 'A typical magnet gives about 0.1 T, so the Earth''s contribution is under 0.1 %. Mark scheme (4 marks). C1: Earth field ~10⁻⁵ T. C1: magnet ~0.1 T. C1: negligible ratio. A1: B (It is about 5 × 10⁻⁵ T, thousands of times smaller than the magnet''s field).', 4),
('ff4eec0e-a27c-5254-bfeb-4dd60c0cdbee', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 35, 35, 'A wire with 0.050 m in a field of 0.10 T is to change a balance reading by 1.0 g. Calculate the current needed. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '1.962', 'A', false, NULL, false, NULL, 'F = 1.0 × 10⁻³ × 9.81 = 9.81 × 10⁻³ N. I = F/(BL) = 9.81 × 10⁻³ ÷ (0.10 × 0.050) = 1.96 A. Mark scheme (3 marks). C1: F = Δm g. C1: I = F/(BL). A1: I = 1.96 A.', 3),
('ee5c488e-49fd-56de-8e32-6f44db0fa1ce', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 36, 36, 'A solenoid has 1500 turns per metre and carries 1.3 A. Calculate the flux density predicted by B = µ₀nI, in mT, for comparison with a Hall-probe reading. Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 2, 'numeric'::answer_type, '2.45 mT', 'mT', false, NULL, false, NULL, 'B = 4π × 10⁻⁷ × 1500 × 1.3 = 0.00245 T. In mT: 0.002450 × 1000 = 2.45. Mark scheme (4 marks). C1: B = µ₀nI. C1: substitution. C1: conversion. A1: B = 2.45 mT.', 4),
('55d3ce8d-6743-5f6a-b82e-bb7bf82a3f01', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 37, 37, 'A Hall probe in a uniform field is slowly rotated. In which position does its reading fall to zero?', NULL, 2, 'multiple_choice'::answer_type, 'When its flat face is parallel to the field lines', NULL, false, NULL, false, NULL, 'Then the field has no component perpendicular to the face. Mark scheme (3 marks). C1: perpendicular component zero. C1: face parallel to B. A1: C (When its flat face is parallel to the field lines).', 3),
('03de3ada-209e-5b54-9e20-cc30db2d4567', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 38, 38, 'With the current one way the balance reads 100.62 g; with it reversed the reading is 99.38 g. Calculate the magnetic force, in mN. Take g = 9.81 m s⁻².', NULL, 2, 'numeric'::answer_type, '6.082 mN', 'mN', false, NULL, false, NULL, 'The change each way is (100.62 − 99.38) ÷ 2 = 0.62 g. F = 0.62 × 10⁻³ × 9.81 = 0.00608 N. In mN: 0.006082 × 1000 = 6.08. Mark scheme (3 marks). M1: half the difference. C1: F = Δm g. A1: F = 6.08 mN.', 3),
('37f4015e-0ad0-52de-aaca-014afda8a7da', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 39, 39, 'A wire in a current balance is accidentally set at 60° to the field. With 3.0 A and 0.050 m in the field, the force is 0.026 N. Calculate the flux density.', NULL, 2, 'numeric'::answer_type, '0.2001', 'T', false, NULL, false, NULL, 'B = F/(IL sin θ) = 0.026 ÷ (3.0 × 0.050 × sin 60°) = 0.200 T. Mark scheme (3 marks). C1: F = BIL sin θ. C1: rearranged. A1: B = 0.200 T.', 3),
('9a151686-0023-5b26-a706-32020d8c8a1b', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 40, 40, 'In a top-pan balance experiment, the length of wire in the field is 0.050 m. Results: I/A = 0.5, 1.0, 1.5, 2.0, 2.5 and change in reading Δm/g = 0.31, 0.61, 0.92, 1.22, 1.53. (a) Describe the relationship shown. (b) Calculate the gradient of the Δm–I graph. (c) Use the gradient to calculate B. Give only the answer to (c). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.1197', 'T', false, NULL, false, NULL, '(a) Δm ∝ I. (b) Gradient = (1.53 − 0.31) ÷ (2.5 − 0.5) = 0.61 g A⁻¹. (c) F = Δm g = BIL, so B = gradient × g ÷ L = 0.61 × 10⁻³ × 9.81 ÷ 0.050 = 0.120 T. Mark scheme (6 marks). B1: proportional. C1: gradient. M1: gradient × g = BL. C1: units converted. C1: B. A1: B = 0.120 T.', 6),
('8f7bc848-0c05-5197-8bae-a0beaf8d2abd', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 41, 41, 'In a top-pan balance experiment: Δm = 1.20 ± 0.02 g, I = 2.00 ± 0.05 A and L = 4.0 ± 0.1 cm. (a) Calculate B. (b) Calculate the percentage uncertainty in B. Give only the answer to (b), in %. Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '6.667', '%', false, NULL, false, NULL, '(a) B = 1.20 × 10⁻³ × 9.81 ÷ (2.00 × 0.040) = 0.147 T. (b) Percentage uncertainty = (0.02 ÷ 1.20 + 0.05 ÷ 2.00 + 0.1 ÷ 4.0) × 100 = 6.67 %. Mark scheme (5 marks). C1: B = Δm g/(IL). C1: each percentage. M1: add percentages. C1: value. A1: uncertainty = 6.7%.', 5),
('04b4cdda-81a6-567a-a40e-ad27a7f6ce21', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 42, 42, 'A Hall probe is moved along the axis of a long solenoid that carries 2.0 A. It reads 5.0 mT near the centre and about 2.5 mT at each end. (a) Explain why the field at the ends is about half the central value. (b) Use B = µ₀nI to calculate the number of turns per metre. Give only the answer to (b). Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '1989', 'm⁻¹', false, NULL, false, NULL, '(a) At an end there are turns on one side only, so only about half of the contributions are present. (b) n = B/(µ₀I) = 5.0 × 10⁻³ ÷ (4π × 10⁻⁷ × 2.0) = 1990 m⁻¹. Mark scheme (6 marks). B1: turns on one side only. B1: half the contribution. M1: n = B/(µ₀I). C1: substitution. C1: value. A1: n = 1990 m⁻¹.', 6),
('2e028099-88f0-565c-94df-ccfd2a6fe66a', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 43, 43, 'A wire frame on knife edges carries 2.5 A, with a 6.0 cm side at right angles to a magnetic field. The magnetic force on that side is balanced by a 0.20 g mass hung on the same side of the frame at the same distance from the pivot. (a) Explain why the force on the wire equals the weight of the mass. (b) Calculate the flux density, in mT. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '13.08 mT', 'mT', false, NULL, false, NULL, '(a) Both act at the same distance from the pivot, so equal moments need equal forces. (b) B = mg/(IL) = 0.20 × 10⁻³ × 9.81 ÷ (2.5 × 0.060) = 0.0131 T. In mT: 0.01308 × 1000 = 13.1. Mark scheme (5 marks). B1: equal moments at equal distance. C1: weight in N. C1: B = F/(IL). C1: conversion. A1: B = 13.1 mT.', 5),
('b29d22ee-b3b5-55a4-8987-76d0fc8681e9', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 44, 44, 'A Hall probe gives 18 mV inside a long solenoid with 2400 turns per metre carrying 1.5 A. It then gives 27 mV between the poles of a magnet. (a) Calculate the field inside the solenoid using B = µ₀nI. (b) Calculate the probe''s sensitivity in mV per mT. (c) Calculate the flux density between the poles, in mT. Give only the answer to (c). Take µ₀ = 4π × 10⁻⁷ T m A⁻¹.', NULL, 3, 'numeric'::answer_type, '6.786 mT', 'mT', false, NULL, false, NULL, '(a) B = 4π × 10⁻⁷ × 2400 × 1.5 = 0.00452 T, which is 4.52 mT. (b) Sensitivity = 18 ÷ 4.524 = 3.98 mV per mT. (c) B = 27 ÷ 3.979 = 6.79 mT. Mark scheme (6 marks). C1: B = µ₀nI. C1: in mT. M1: sensitivity = output/B. C1: B = output/sensitivity. B1: calibration idea. A1: B = 6.79 mT.', 6),
('598b9e95-aa09-5ca8-a26f-fa78e4992cfa', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 45, 45, 'A student tries to measure the Earth''s horizontal field with a current balance. A 1.5 m horizontal wire carries 20 A east–west where the horizontal field is 1.8 × 10⁻⁵ T. (a) Calculate the force on the wire, in mN. (b) The balance can resolve 0.01 g. Calculate the percentage uncertainty this gives in the force. Give only the answer to (a). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.54 mN', 'mN', false, NULL, false, NULL, '(a) F = BIL = 1.8 × 10⁻⁵ × 20 × 1.5 = 5.40 × 10⁻⁴ N. In mN: 5.40 × 10⁻⁴ × 1000 = 0.540. (b) Resolution = 0.01 × 10⁻³ × 9.81 = 9.81 × 10⁻⁵ N, so the uncertainty = 9.81 × 10⁻⁵ ÷ 5.40 × 10⁻⁴ × 100 = 18.2 %: far too large for a useful measurement. Mark scheme (5 marks). C1: F = BIL. C1: conversion. C1: resolution as a force. C1: percentage uncertainty. A1: F = 0.540 mN.', 5),
('8f9b4985-7da8-5f57-8573-92c7d5c07437', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 46, 46, 'Hall-probe readings across the 5.0 cm gap between two pole pieces, at the midpoints of 1.0 cm intervals, are B/T = 0.10, 0.18, 0.20, 0.18, 0.10. A wire carrying 3.0 A crosses the gap at right angles to the field. (a) Explain why F ≠ B_max IL. (b) Estimate the force on the wire by adding the forces on each 1.0 cm section. (c) Calculate the average flux density over the gap. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.0228', 'N', false, NULL, false, NULL, '(a) The field is not uniform: it is weaker near the edges. (b) F = IΣBΔx = 3.0 × 0.010 × (0.10 + 0.18 + 0.20 + 0.18 + 0.10) = 0.0228 N. (c) Average B = (0.10 + 0.18 + 0.20 + 0.18 + 0.10) ÷ 5 = 0.152 T. Mark scheme (6 marks). B1: non-uniform field. M1: sum of BIΔx. C1: substitution. C1: force. C1: average B. A1: F = 0.0228 N.', 6),
('a9de5dd1-c11c-50dc-af35-f8f46afac449', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 47, 47, 'A current balance gives B = 0.152 T for the field between two pole pieces, while a Hall probe at the centre of the gap reads 0.160 T. (a) Calculate the percentage difference between the two values, relative to the Hall-probe value. (b) Explain why the current balance gives a smaller value. Give only the answer to (a), in %.', NULL, 3, 'numeric'::answer_type, '5', '%', false, NULL, false, NULL, '(a) (0.160 − 0.152) ÷ 0.160 × 100 = 5.0 %. (b) The balance measures the average field along the wire, which includes the weaker field near the edges; the probe measures the strongest field, at the centre. Mark scheme (5 marks). C1: difference. C1: percentage. B1: balance averages along L. B1: probe at the centre where B is largest. A1: difference = 5.0%.', 5),
('4bbe258a-6f0c-5cf7-87aa-592f2f55836c', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 48, 48, 'A student wants to measure a field of about 50 mT with a top-pan balance that reads to 0.01 g. The length of wire in the field is 5.0 cm. The uncertainty from the balance must be no more than 2 % of the force. (a) Calculate the smallest force that meets this requirement. (b) Calculate the smallest current needed. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '1.962', 'A', false, NULL, false, NULL, '(a) Resolution = 0.01 × 10⁻³ × 9.81 = 9.81 × 10⁻⁵ N, which must be ≤ 2 % of F: F ≥ 9.81 × 10⁻⁵ ÷ 0.02 = 0.00490 N. (b) I = F/(BL) = 0.004905 ÷ (50 × 10⁻³ × 0.050) = 1.96 A. Mark scheme (6 marks). C1: resolution as force. M1: resolution ≤ 2 % of F. C1: minimum F. C1: I = F/(BL). C1: value. A1: I = 1.96 A.', 6),
('dcd3e16e-73c5-5ca2-8d74-524e30955d66', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 49, 49, 'A wire in a current balance is at 70° to the field. With 2.5 A and 0.10 m in the field the measured force is 0.047 N. (a) Calculate the true flux density. (b) Calculate the value a student would get by wrongly assuming the wire was at 90°. (c) Calculate the percentage error this would cause. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '0.2001', 'T', false, NULL, false, NULL, '(a) B = 0.047 ÷ (2.5 × 0.10 × sin 70°) = 0.200 T. (b) B = 0.047 ÷ (2.5 × 0.10) = 0.188 T. (c) Error = (1 − sin 70°) × 100 = 6.03 %. Mark scheme (5 marks). C1: F = BIL sin θ. C1: true B. C1: wrong B. C1: percentage error. A1: B = 0.200 T.', 5),
('bf27f987-8729-5cb3-bc6d-9cea53eb06a9', '451c0a56-584e-41c1-958b-7b940530308c', 'afcda447-9d59-47a9-b3e4-68d27e28446a', 'a-level', '24.4', '9702 coursebook 24.4 · Measuring magnetic flux density', 50, 50, 'A magnet assembly on a top-pan balance reads 150.00 g. A wire crossing its field for 4.0 cm carries 3.0 A, and the reading rises to 150.65 g. (a) Calculate the force on the magnet. (b) Calculate the flux density. (c) State the direction of the force on the wire. (d) Predict the reading when the current is 1.0 A. Give only the answer to (b). Take g = 9.81 m s⁻².', NULL, 3, 'numeric'::answer_type, '0.05314', 'T', false, NULL, false, NULL, '(a) F = 0.65 × 10⁻³ × 9.81 = 0.00638 N, downwards on the magnet. (b) B = 0.006377 ÷ (3.0 × 0.040) = 0.0531 T. (c) Upwards: equal and opposite to the force on the magnet. (d) F ∝ I, so the change is 0.65 ÷ 3 = 0.22 g and the reading is 150.22 g. Mark scheme (6 marks). C1: F = Δm g. C1: B = F/(IL). B1: Newton''s third law. C1: change ∝ I. C1: new reading. A1: B = 0.0531 T.', 6)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('5b521baf-b674-5cec-b91a-fc2b64820758', '4173550b-61a9-5ca4-ae3f-7d5e0f25a579', 'The total current in the circuit being tested', 'A', false, 0),
('b620a74f-484d-57d6-848f-4aaf6877139e', '4173550b-61a9-5ca4-ae3f-7d5e0f25a579', 'The temperature of the magnet only', 'B', false, 1),
('a5fce633-9ba5-5f8c-9077-0e1fb62b3621', '4173550b-61a9-5ca4-ae3f-7d5e0f25a579', 'The component of the magnetic flux density at right angles to the probe''s flat face', 'C', true, 2),
('f8e9bd6b-c1de-56ec-8ab9-a75f48cabe97', '4173550b-61a9-5ca4-ae3f-7d5e0f25a579', 'The electric field around the probe', 'D', false, 3),
('f012261a-b806-57c2-a133-fa605b6e6100', 'de1df757-0de6-5c9d-a9ce-2cf2ece1c617', 'The magnet pushes up on the wire, so by Newton''s third law the wire pushes down on the magnet', 'A', true, 0),
('d2c0ded8-dec4-5900-b476-4c4c9cc45f4e', 'de1df757-0de6-5c9d-a9ce-2cf2ece1c617', 'The current adds weight to the wire', 'B', false, 1),
('ec2dd6e1-9ea8-5335-ba2f-e6e3e774a805', 'de1df757-0de6-5c9d-a9ce-2cf2ece1c617', 'The magnet becomes heavier', 'C', false, 2),
('ba7d1e72-4eaa-5126-9f7b-8e94cae5fff3', 'de1df757-0de6-5c9d-a9ce-2cf2ece1c617', 'The balance is affected by the current directly', 'D', false, 3),
('5047d773-bd6e-5375-af17-ad52a7e2cf3f', '9a7a510d-1ee0-5961-9e46-1b288d0c3047', 'With its flat face parallel to the field lines', 'A', false, 0),
('9667b9ff-397e-52cc-a665-97a3690f8c7b', '9a7a510d-1ee0-5961-9e46-1b288d0c3047', 'Pointing towards the north pole', 'B', false, 1),
('c3e4c950-a199-5f54-8e64-808eb0e9b53c', '9a7a510d-1ee0-5961-9e46-1b288d0c3047', 'At 45° to the field', 'C', false, 2),
('3df2b830-2ddf-5e8f-81b3-6017a47b7164', '9a7a510d-1ee0-5961-9e46-1b288d0c3047', 'With its flat face at right angles to the field lines', 'D', true, 3),
('0217c6e7-447c-5a13-a983-1ce00501614f', 'a112e956-10b0-5379-bad1-2c28356d705a', 'To double the current', 'A', false, 0),
('1a4a1540-3d0f-5b93-8a29-2ddb5cb7bec0', 'a112e956-10b0-5379-bad1-2c28356d705a', 'To check that the change reverses, so that effects not due to the magnetic force can be averaged out', 'B', true, 1),
('536a1e18-ce46-5aa4-85b2-286d1a261dee', 'a112e956-10b0-5379-bad1-2c28356d705a', 'To demagnetise the magnet', 'C', false, 2),
('890c93dc-4d70-5fe9-9c7e-a77d7671d3be', 'a112e956-10b0-5379-bad1-2c28356d705a', 'To keep the wire cool', 'D', false, 3),
('93caaf19-9e5d-53e4-8439-494d59eafccf', '1842a526-2e59-544d-aac0-784142ecb9b5', 'It needs no electrical supply', 'A', false, 0),
('4824f581-4bb0-554a-9e2d-2c16fcb637c1', '1842a526-2e59-544d-aac0-784142ecb9b5', 'It averages the field over a long length', 'B', false, 1),
('ab70bfb2-bbf9-5ae0-8aa6-f111c2ebd45f', '1842a526-2e59-544d-aac0-784142ecb9b5', 'It measures the field at a point, so it can map how the field varies', 'C', true, 2),
('378f3742-b6c5-5d71-81d4-9cc189a1f1ac', '1842a526-2e59-544d-aac0-784142ecb9b5', 'It measures the current in the wire', 'D', false, 3),
('648a2b1a-930b-5831-95d9-42442d8fda13', '49bf27f3-0bc3-5f8e-9bf6-1d7ecc545835', 'It decreases, because only the perpendicular component of B is measured', 'A', true, 0),
('a549b4b9-2c79-5e59-a713-c7ab4f4b72cc', '49bf27f3-0bc3-5f8e-9bf6-1d7ecc545835', 'It increases', 'B', false, 1),
('abe89488-4c32-58f6-a203-c841f45f9bbf', '49bf27f3-0bc3-5f8e-9bf6-1d7ecc545835', 'It stays the same', 'C', false, 2),
('6b042d3a-4594-5c61-bfb7-99ee59935497', '49bf27f3-0bc3-5f8e-9bf6-1d7ecc545835', 'It reverses', 'D', false, 3),
('602a1cfc-a393-53bb-94ca-74c7121ed729', 'b6676c2f-aafb-5f4e-b928-0091266c217c', 'The voltage, the resistance and the time', 'A', false, 0),
('8759cbb4-bc5c-54cd-84dd-0ede8e2e25cd', 'b6676c2f-aafb-5f4e-b928-0091266c217c', 'The mass of the magnet, its length and its temperature', 'B', false, 1),
('4c4125b7-4edf-51ad-a98c-e7fc3add41d6', 'b6676c2f-aafb-5f4e-b928-0091266c217c', 'The charge, the speed and the radius', 'C', false, 2),
('704d8228-4e39-5106-acf6-7f8ef38fc905', 'b6676c2f-aafb-5f4e-b928-0091266c217c', 'The force on the wire, the current, and the length of wire in the field', 'D', true, 3),
('e44c5fc9-3ef5-5a4e-9d6e-710f3b118339', 'b2c392b0-fc24-584a-8ad2-58199a637eae', 'To measure the Earth''s field', 'A', false, 0),
('6abe9483-2754-5147-a28d-b8a7c6651255', 'b2c392b0-fc24-584a-8ad2-58199a637eae', 'It is the zero reading: only the change from it is due to the magnetic force', 'B', true, 1),
('a06da3fb-0edd-53d6-9cff-276a30d23b37', 'b2c392b0-fc24-584a-8ad2-58199a637eae', 'To find the current', 'C', false, 2),
('8aefd09a-fcda-582d-9079-5c3f79a16bfb', 'b2c392b0-fc24-584a-8ad2-58199a637eae', 'To calibrate the ammeter', 'D', false, 3),
('9e414e92-c23c-591d-8a95-7958ca84a070', '94670dec-7898-5469-88c2-1bccc0ef78dd', 'The reading increases by twice as much', 'A', false, 0),
('b7e49b63-8250-5769-b8e5-67073a5d4a2c', '94670dec-7898-5469-88c2-1bccc0ef78dd', 'The reading stays the same', 'B', false, 1),
('7d487cdd-4d58-5439-b9d2-c8a5134b3c82', '94670dec-7898-5469-88c2-1bccc0ef78dd', 'The reading decreases below the zero value by the same amount', 'C', true, 2),
('d6b4de8e-0b3e-5764-96ab-86e65715e513', '94670dec-7898-5469-88c2-1bccc0ef78dd', 'The reading returns to zero', 'D', false, 3),
('5a0a1951-f8f7-5c65-9f4b-5504936380e5', '9fb3ade6-67f4-58a8-ae77-ae345cef8002', 'So that B is the same along the whole length L used in F = BIL', 'A', true, 0),
